import {it,expect,vi,beforeEach,afterEach} from 'vitest';
vi.mock('../../store/authStore',()=>({useAuthStore:{setState:vi.fn()}}));
import {setToken,getToken,apiRequest,isTokenExpired,getTokenExpiry} from '../client';
import {guestLogin} from '../auth';
beforeEach(()=>{let cookie='';const memory=new Map<string,string>();vi.stubGlobal('localStorage',{getItem:(key:string)=>memory.get(key)||null,setItem:(key:string,value:string)=>memory.set(key,value),removeItem:(key:string)=>memory.delete(key)});vi.stubGlobal('document',{get cookie(){return cookie;},set cookie(value:string){cookie=value.split(';')[0];}});vi.stubGlobal('window',{location:{pathname:'/login',search:'',href:''}});});
afterEach(()=>vi.unstubAllGlobals());
it('guest request has an explicit JSON body, no stale bearer token and a bounded timeout',async()=>{setToken('old-token');const fetch=vi.fn(async(_url:any,_options:any)=>Response.json({session_token:'guest-token'}));vi.stubGlobal('fetch',fetch);await guestLogin();expect(fetch.mock.calls[0][1]).toMatchObject({method:'POST',body:'{}'});expect(fetch.mock.calls[0][1].headers.Authorization).toBeUndefined();expect(fetch.mock.calls[0][1].signal).toBeInstanceOf(AbortSignal);});
it('late 401 from an old session cannot remove a newly connected guest token',async()=>{setToken('old-token');let resolve!:any;vi.stubGlobal('fetch',vi.fn(()=>new Promise(r=>{resolve=r;})));const pending=apiRequest('/auth/me').catch(error=>error);setToken('new-guest-token');resolve(Response.json({error:'unauthorized'},{status:401}));await pending;expect(getToken()).toBe('new-guest-token');expect(window.location.href).toBe('');});
it('invalid JWTs are expired and a guest JWT keeps its exact expiry',()=>{const exp=Math.floor(Date.now()/1000)+86400;const token='header.'+btoa(JSON.stringify({exp}))+'.signature';expect(getTokenExpiry(token)).toBe(exp*1000);expect(isTokenExpired(token)).toBe(false);expect(isTokenExpired('not-a-token')).toBe(true);});

import {contract} from '../../../shared/document-contract.mjs';
import { get, post, patch, getToken, apiRequest } from './client';
import { ChatStreamError, readChatStream, chatErrorFromHttp, validSnapshot } from '../../../shared/chat-stream.mjs';
import type { SessionStartRequest, SessionStartResponse, ChatRequest, ChatResponse, AISummaryResponse, MissingFieldsRequest, MissingFieldsResponse, CorrectionConfirmRequest, CorrectionConfirmResponse, ConversationSnapshot } from '../types';
export { ChatStreamError };
const base = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3001/v1';
const path = (id: string) => '/chat/api/chat/session/' + encodeURIComponent(id);
export async function startSession(data: SessionStartRequest & {
    template_id?: string;
    reuse_from_session_id?: string;
}): Promise<SessionStartResponse> {
    if (!getToken())
        await (await import('../store/authStore')).useAuthStore.getState().guestLogin();
    const response = await post<{
        state: ConversationSnapshot;
        opening_message: string;
    }>('/chat/api/chat/session', { documentTypeId: data.document_type, templateId: data.template_id || 'tmpl_invoice_2023_01', reuseFromSessionId: data.reuse_from_session_id, timezone:Intl.DateTimeFormat().resolvedOptions().timeZone });
    const s = response.state;
    if (!validSnapshot(s))
        throw new Error('Session state was not returned');
    return { state: s, session_id: s.sessionId, document_type: s.documentType, opening_message: response.opening_message, schema_summary: s.schema, collected_slots: s.slots, pending_required: s.missingRequired, pending_optional: s.pendingOptional };
}
export async function sendChatMessage(data: ChatRequest): Promise<ChatResponse> {
    const requestToken=getToken();
    const turnId = data.turn_id || crypto.randomUUID();
    let response: Response;
    try {
        response = await fetch(base + path(data.session_id) + '/message', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'text/event-stream', 'Authorization': 'Bearer ' + (requestToken || '') }, body: JSON.stringify({ message: data.message, turnId }), signal: data.signal });
    } catch (error) {
        const cancelled = data.signal?.aborted || error instanceof Error && error.name === 'AbortError';
        throw new ChatStreamError(cancelled ? 'cancelled' : 'failure', cancelled ? 499 : 503, undefined, cancelled ? 'REQUEST_CANCELLED' : 'NETWORK_UNAVAILABLE');
    }
    if (!response.ok) {
        if (response.status === 401&&getToken()===requestToken)
            void import('../store/authStore').then(m => {if(getToken()===requestToken)m.useAuthStore.setState({ user:null,isAuthenticated:false,isGuest:false,guestSession:null });});
        let errorBody:unknown;try{errorBody=await response.json();}catch{ /* The status still yields a categorized transport error. */ }
        throw chatErrorFromHttp(errorBody,response.status);
    }
    const event = await readChatStream(response.body, { sessionId: data.session_id, turnId });
    const s = event.state as ConversationSnapshot;
    return { state: s, turn_id: turnId, session_id: s.sessionId, ai_message: event.response, actions:event.actions||[], current_field: s.nextAction.field, status: s.readyToGenerate ? 'complete' : 'ok', collected_slots: s.slots, pending_required: s.missingRequired, pending_optional: s.pendingOptional, ready_to_generate: s.readyToGenerate };
}
export async function getSummary(sessionId: string): Promise<AISummaryResponse> {const response=await get<AISummaryResponse>(path(sessionId)+'/messages');if(!validSnapshot(response.state)||response.state.sessionId!==sessionId)throw new ChatStreamError('incomplete',502,undefined,'INVALID_COMPLETION');return response;}
export async function confirmDocument(sessionId:string,fingerprint:string,expectedRevision:number) {return post<{state:ConversationSnapshot}>(path(sessionId)+'/confirm',{fingerprint,expectedRevision});}
export async function saveDocumentAsset(sessionId:string, asset:import('../../../shared/document-assets.mjs').DocumentAsset, expectedRevision:number) {
    const {id,role,name,src,width,height}=asset;
    const response=await post<{state:ConversationSnapshot}>(path(sessionId)+'/assets',{asset:{id,role,name,src,width,height},expectedRevision});
    if(!validSnapshot(response.state)||response.state.sessionId!==sessionId)throw new ChatStreamError('incomplete',502,undefined,'INVALID_COMPLETION');
    return response;
}
export async function removeDocumentAssets(sessionId:string, ids:string[],expectedRevision:number) {
    const response=await apiRequest<{state:ConversationSnapshot}>(path(sessionId)+'/assets',{method:'DELETE',body:{ids,expectedRevision}});
    if(!validSnapshot(response.state)||response.state.sessionId!==sessionId)throw new ChatStreamError('incomplete',502,undefined,'INVALID_COMPLETION');
    return response;
}
export async function getMissingFields(data: MissingFieldsRequest): Promise<MissingFieldsResponse> {
    const { state } = await getSummary(data.session_id);
    return { session_id: state.sessionId, document_type: state.documentType, collected_count: Object.values(state.fieldStates).filter((field:any)=>field.status==='confirmed').length, total_required: state.schema.required_fields, completion_percent: Math.round(100 * (state.schema.required_fields - state.missingRequired.length) / Math.max(1, state.schema.required_fields)), missing_required: state.missingRequired.map(key => ({ key, label: contract.fields[key].label, type: contract.fields[key].type })), missing_optional: state.pendingOptional.map(key => ({ key, label: contract.fields[key].label, type: contract.fields[key].type })), ready_to_generate: state.readyToGenerate };
}
export async function confirmCorrection(data: CorrectionConfirmRequest): Promise<CorrectionConfirmResponse> {
    const { state } = await post<{
        state: ConversationSnapshot;
    }>(path(data.session_id) + '/resolve', { field: data.field, accept: data.accept });
    return { session_id: state.sessionId, field: data.field, saved_value: String(state.slots[data.field] || ''), accepted_correction: data.accept, next_field: state.nextAction.field || '', ai_message: state.nextAction.question, collected_slots: state.slots, pending_required: state.missingRequired };
}
export async function listUserSessions() { const response = await get<{
    sessions: Array<{
        id: string;
        title?: string;
        documentTypeId?: string;
        updatedAt?: string;
        status?: string;
    }>;
}>('/chat/api/chat/sessions'); return response.sessions; }
export async function deleteUserSession(id: string) { await fetchOrThrow(path(id), 'DELETE'); return true; }
async function fetchOrThrow(endpoint: string, method: string) { const requestToken=getToken(); const r = await fetch(base + endpoint, { method, headers: { Authorization: 'Bearer ' + (requestToken || '') } }); if (!r.ok)
    throw new Error('Session operation failed. Please retry.'); }
export async function updateSessionTemplate(id: string, templateId: string) { const result=await patch<{state:ConversationSnapshot}>(path(id), { templateId });if(!validSnapshot(result.state))throw new ChatStreamError('incomplete',502,undefined,'INVALID_COMPLETION');return result; }
export async function updateSessionAccentColor(id: string, accentColor: string) { const result=await patch<{state:ConversationSnapshot}>(path(id), { accentColor });if(!validSnapshot(result.state))throw new ChatStreamError('incomplete',502,undefined,'INVALID_COMPLETION');return result; }
export async function updateSemanticFields(id: string, slots: Record<string, unknown>, expectedRevision: number) { return patch<{
    state: ConversationSnapshot;
}>(path(id), { slots, expectedRevision }); }

/**
 * Centralized API Client for DocCraft
 * All HTTP requests to the backend go through this module.
 * Base URL is configured via VITE_API_BASE_URL environment variable.
 */

import type { ApiError } from '../types';

const BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3001/v1';

/** Set cookie for token persistence */
export function setCookieToken(token: string, days = 7): void {
  if (typeof document === 'undefined') return;
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  document.cookie = `doccraft_token=${encodeURIComponent(token)}; expires=${expires}; path=/; SameSite=Lax`;
}

/** Get token from cookies */
export function getCookieToken(): string | null {
  if (typeof document === 'undefined') return null;
  const name = 'doccraft_token=';
  try {
    const decodedCookie = decodeURIComponent(document.cookie);
    const ca = decodedCookie.split(';');
    for (let i = 0; i < ca.length; i++) {
      let c = ca[i].trim();
      if (c.indexOf(name) === 0) {
        return c.substring(name.length, c.length);
      }
    }
  } catch {
    // Return null if cookie string cannot be decoded
  }
  return null;
}

/** Clear token cookie */
export function clearCookieToken(): void {
  if (typeof document === 'undefined') return;
  document.cookie = 'doccraft_token=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/; SameSite=Lax';
}

/** Check if JWT token is expired */
export function getTokenExpiry(token: string): number | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const payload = JSON.parse(atob(parts[1].replace(/-/g, '+').replace(/_/g, '/')));
    if (payload && typeof payload.exp === 'number') {
      return payload.exp * 1000;
    }
  } catch {
    return null;
  }
  return null;
}

export function isTokenExpired(token: string): boolean {
  if (token === 'demo_token_for_testing') return false;
  const expiry = getTokenExpiry(token);
  return expiry === null || Date.now() >= expiry - 10000;
}

/** Get the auth token from cookie first, then localStorage */
export function getToken(): string | null {
  const cookieToken = getCookieToken();
  if (cookieToken) return cookieToken;
  return localStorage.getItem('doccraft_token');
}

/** Set the auth token in both cookie and localStorage */
export function setToken(token: string): void {
  localStorage.setItem('doccraft_token', token);
  setCookieToken(token, 7);
}

/** Clear the auth token from both cookie and localStorage */
export function clearToken(): void {
  localStorage.removeItem('doccraft_token');
  clearCookieToken();
}


/** Custom error class for API errors */
export class ApiRequestError extends Error {
  status: number;
  code: string;
  details?: Record<string, unknown>;

  constructor(status: number, body: ApiError) {
    const errMsg = body.message || (typeof body.error === 'string' ? body.error : `Request failed with status ${status}`);
    super(errMsg);
    this.name = 'ApiRequestError';
    this.status = status;
    this.code = typeof body.error === 'string' ? body.error : 'API_ERROR';
    this.details = body.details;
  }
}

interface RequestOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE';
  body?: unknown;
  headers?: Record<string, string>;
  auth?: boolean;
  responseType?: 'json' | 'blob';
  timeoutMs?: number;
}

/**
 * Core fetch wrapper.
 * - Automatically injects Bearer token for authenticated requests
 * - Serializes JSON bodies
 * - Parses error responses into ApiRequestError
 */
export async function apiRequest<T>(
  endpoint: string,
  options: RequestOptions = {}
): Promise<T> {
  const {
    method = 'GET',
    body,
    headers = {},
    auth = true,
    responseType = 'json',
    timeoutMs,
  } = options;

  const url = `${BASE_URL}${endpoint}`;

  const requestHeaders: Record<string, string> = {
    'Content-Type': 'application/json',
    ...headers,
  };

  const requestToken = auth ? getToken() : null;
  if (requestToken) {
      requestHeaders['Authorization'] = `Bearer ${requestToken}`;
  }

  const fetchOptions: RequestInit = {
    method,
    headers: requestHeaders,
    ...(timeoutMs ? { signal: AbortSignal.timeout(timeoutMs) } : {}),
  };

  if (body && method !== 'GET') {
    fetchOptions.body = JSON.stringify(body);
  }

  const response = await fetch(url, fetchOptions);

  if (!response.ok) {
    if (response.status === 401 && auth && getToken() === requestToken) {
      clearToken();
      import('../store/authStore').then((m) => {
        if (getToken()) return; // A newer login completed during the import.
        m.useAuthStore.setState({
          user: null,
          isAuthenticated: false,
          isGuest: false,
          guestSession: null,
          isInitializing: false,
        });
      }).catch(() => {});
      if (typeof window !== 'undefined' && !window.location.pathname.startsWith('/login') && !window.location.search.includes('new=true')) {
        window.location.href = `/login?expired=true`;
      }
    }
    let errorBody: ApiError;
    try {
      errorBody = await response.json();
    } catch {
      errorBody = {
        error: 'request_failed',
        message: response.status === 401 ? 'Invalid email or password.' : `Request failed with status ${response.status}`,
      };
    }
    throw new ApiRequestError(response.status, errorBody);
  }

  if (responseType === 'blob') {
    return (await response.blob()) as unknown as T;
  }

  // Handle empty responses (204 No Content)
  const text = await response.text();
  if (!text) {
    return {} as T;
  }

  return JSON.parse(text) as T;
}

/** Shorthand for GET requests */
export function get<T>(endpoint: string, auth = true): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'GET', auth });
}

/** Shorthand for POST requests */
export function post<T>(endpoint: string, body?: unknown, auth = true): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'POST', body, auth });
}

/** Shorthand for PATCH requests */
export function patch<T>(endpoint: string, body?: unknown, auth = true): Promise<T> {
  return apiRequest<T>(endpoint, { method: 'PATCH', body, auth });
}

/**
 * Document Generation API endpoints
 * Maps to: POST /documents/generate, PATCH /documents/{id}/layout,
 *          PATCH /documents/{id}/content, GET /templates, POST /documents/{id}/export/pdf
 */

import { post, patch, get, apiRequest } from './client';
import type {
  GenerateDocumentRequest,
  GenerateDocumentResponse,
  LayoutUpdateRequest,
  LayoutUpdateResponse,
  ContentUpdateRequest,
  ContentUpdateResponse,
  TemplatesResponse,
  DocumentType,
} from '../types';

/** POST /document/preview — Render live HTML preview */
export function generateDocument(data: GenerateDocumentRequest): Promise<GenerateDocumentResponse> {
  return post<{documentId:string;jobId:string;status:string}>('/documents/generate', {
    operationId:data.operation_id,expectedRevision:data.expected_revision,sessionId:data.session_id,documentType:data.document_type,templateId:data.template_id,slots:data.data,
  }).then(response => ({document_id:response.documentId,job_id:response.jobId,status:response.status}));
}

/** PATCH /documents/{id}/layout — Update layout/formatting */
export function updateLayout(documentId: string, data: LayoutUpdateRequest): Promise<LayoutUpdateResponse> {
  return patch<LayoutUpdateResponse>(`/documents/${documentId}/layout`, data);
}

/** PATCH /documents/{id}/content — Update data content fields */
export function updateContent(documentId: string, data: ContentUpdateRequest): Promise<ContentUpdateResponse> {
  return patch<ContentUpdateResponse>(`/documents/${documentId}/content`, data);
}

/** GET /document/templates?document_type=... — Get available templates */
export function getTemplates(documentType: DocumentType): Promise<TemplatesResponse> {
  return get<TemplatesResponse>(`/document/templates?type=${documentType}`).catch(() => {
    return get<TemplatesResponse>(`/templates?document_type=${documentType}`);
  });
}

/** GET /chat/sessions — Get document history from database */
export function getUserDocuments(): Promise<{ sessions: any[] }> {
  return get<{ sessions: any[] }>('/chat/sessions').catch(() => {
    return { sessions: [] };
  });
}

/** GET /chat/session/:sessionId/messages — Get session & slot details from database */
export function getSessionDetails(sessionId: string): Promise<any> {
  return get<any>(`/chat/session/${sessionId}/messages`);
}

export interface CustomTemplateSummary {
  id: string;
  name: string;
  documentType: string;
  pageWidth: number | null;
  pageHeight: number | null;
  pageBackgroundColor: string | null;
  createdAt: string;
}

export interface CustomTemplateDetail extends CustomTemplateSummary {
  canvasElements: unknown[];
}

/** POST /document/templates/custom — Save the current Builder canvas as a reusable template */
export function saveCustomTemplate(payload: {
  name: string;
  documentType: string;
  canvasElements: unknown[];
  pageWidth?: number;
  pageHeight?: number;
  pageBackgroundColor?: string;
}): Promise<CustomTemplateDetail> {
  return post<CustomTemplateDetail>('/document/templates/custom', payload);
}

/** GET /document/templates/custom?type=... — List the current user's saved templates */
export function getCustomTemplates(documentType: string): Promise<{ templates: CustomTemplateSummary[] }> {
  return get<{ templates: CustomTemplateSummary[] }>(`/document/templates/custom?type=${documentType}`);
}

/** GET /document/templates/custom/{id} — Fetch a saved template's full canvasElements */
export function getCustomTemplateDetail(id: string): Promise<CustomTemplateDetail> {
  return get<CustomTemplateDetail>(`/document/templates/custom/${id}`);
}

/** DELETE /document/templates/custom/{id} */
export function deleteCustomTemplate(id: string): Promise<{ success: boolean }> {
  return apiRequest<{ success: boolean }>(`/document/templates/custom/${id}`, { method: 'DELETE' });
}

/** POST /document/generate — Generate and download PDF */
export function exportPdf(documentId: string): Promise<Blob> {
  return apiRequest<Blob>(`/document/generate`, {
    method: 'POST',
    body: { documentId },
    responseType: 'blob',
  }).catch(() => {
    return apiRequest<Blob>(`/documents/${documentId}/export/pdf`, {
      method: 'POST',
      responseType: 'blob',
    });
  });
}

export function getDocumentStatus(id: string): Promise<{status:string;errorMessage?:string}> {return get('/documents/'+encodeURIComponent(id));}

import { apiRequest } from './client';

export interface PaymentMethodItem {
  id: string;
  brand: 'visa' | 'mastercard' | 'amex' | 'discover' | 'generic';
  last4: string;
  cardholderName: string;
  expMonth: number;
  expYear: number;
  isDefault: boolean;
}
export interface AddPaymentMethodPayload {
  cardNumber: string;
  cardholderName: string;
  expMonth: number;
  expYear: number;
  cvc?: string;
}
export interface SubscriptionData { plan: string; subscription: any | null; }
export interface CheckoutSession {
  checkout_url: string;
  gateway?: string;
  form_data?: Record<string, string>;
}
export function getPaymentMethods(): Promise<{ methods: PaymentMethodItem[] }> {
  return apiRequest('/payment/methods');
}
export function addPaymentMethod(data: AddPaymentMethodPayload): Promise<{ success: boolean; method: PaymentMethodItem }> {
  return apiRequest('/payment/methods', { method: 'POST', body: data });
}
export function deletePaymentMethod(id: string): Promise<{ success: boolean }> {
  return apiRequest(`/payment/methods/${encodeURIComponent(id)}`, { method: 'DELETE' });
}
export function setDefaultPaymentMethod(id: string): Promise<{ success: boolean }> {
  return apiRequest(`/payment/methods/${encodeURIComponent(id)}/default`, { method: 'POST' });
}
export function getSubscription(): Promise<SubscriptionData> {
  return apiRequest('/payment/subscription');
}
export function createCheckoutSession(billingCycle: 'monthly' | 'yearly' = 'monthly'): Promise<CheckoutSession> {
  return apiRequest('/payment/subscribe', { method: 'POST', body: { billingCycle } });
}
export function cancelSubscription(): Promise<{ success: boolean; message: string }> {
  return apiRequest('/payment/cancel', { method: 'POST' });
}
export function getBillingPortal(): Promise<{ portal_url: string | null; available: boolean; message?: string }> {
  return apiRequest('/payment/portal', { method: 'POST' });
}

/** Use the provider checkout returned by the server; entitlements come from webhooks. */
export function redirectToCheckout(session: CheckoutSession): void {
  const target = new URL(session.checkout_url);
  if (!['http:', 'https:'].includes(target.protocol)) throw new Error('Invalid checkout URL');
  if (session.gateway === 'payhere') {
    if (!session.form_data) throw new Error('Checkout form data is missing');
    const form = document.createElement('form');
    form.method = 'POST';
    form.action = target.href;
    for (const [name, value] of Object.entries(session.form_data)) {
      const field = document.createElement('input');
      field.type = 'hidden'; field.name = name; field.value = String(value);
      form.appendChild(field);
    }
    document.body.appendChild(form);
    try { form.submit(); } finally { form.remove(); }
  } else {
    window.location.assign(target.href);
  }
}

import React, { useRef, useState } from 'react';
import ReactCrop, { centerCrop, type PercentCrop, type PixelCrop } from 'react-image-crop';
import 'react-image-crop/dist/ReactCrop.css';
import { Upload, X, Wand2, PenTool, ImagePlus } from 'lucide-react';
import { removeBackground } from '../../utils/removeBackground';
import SignaturePad from './SignaturePad';

interface AssetModalProps {
  mode: 'image' | 'signature';
  onClose: () => void;
  onAdd: (dataUrl: string) => void;
}

// The crop step used to be squeezed into the ~300px toolkit panel — moved
// here into a real popup with room to actually work, plus a "Remove
// background" step (see utils/removeBackground.ts for why this is a plain
// canvas flood-fill rather than an AI model). Signature mode adds an
// Upload/Draw switch on top of the same crop flow; Draw skips straight to
// the signature pad since a freehand drawing is already exactly what's
// wanted, no cropping needed.
const AssetModal: React.FC<AssetModalProps> = ({ mode, onClose, onAdd }) => {
  const [subMode, setSubMode] = useState<'upload' | 'draw'>('upload');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const [pendingSrc, setPendingSrc] = useState<string | null>(null);
  const [crop, setCrop] = useState<PercentCrop>();
  const [completedCrop, setCompletedCrop] = useState<PixelCrop>();
  const [isDragOver, setIsDragOver] = useState(false);
  const [bgRemoved, setBgRemoved] = useState(false);
  const [removingBg, setRemovingBg] = useState(false);

  const loadFile = (file: File | undefined) => {
    if (!file || !file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = () => {
      setPendingSrc(reader.result as string);
      setCrop(undefined);
      setCompletedCrop(undefined);
      setBgRemoved(false);
    };
    reader.readAsDataURL(file);
  };

  const handleImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    // Only set an initial centered crop once — re-loading the image after
    // "Remove background" swaps pendingSrc and re-fires onLoad, and we
    // don't want that to silently discard whatever crop the user already
    // dragged into place.
    if (crop) return;
    const { width, height } = e.currentTarget;
    setCrop(centerCrop({ unit: '%', width: 90, height: 90 }, width, height));
  };

  const handleRemoveBackground = () => {
    if (!imgRef.current) return;
    setRemovingBg(true);
    // Deferred a tick so the "Removing…" label actually paints before the
    // synchronous pixel-scan work (can take a moment on a big image) blocks
    // the main thread.
    setTimeout(() => {
      const img = imgRef.current;
      if (!img) { setRemovingBg(false); return; }
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) { setRemovingBg(false); return; }
      ctx.drawImage(img, 0, 0);
      removeBackground(canvas);
      setPendingSrc(canvas.toDataURL('image/png'));
      setBgRemoved(true);
      setRemovingBg(false);
    }, 30);
  };

  const handleAdd = () => {
    if (!imgRef.current || !completedCrop || !completedCrop.width || !completedCrop.height) return;
    const image = imgRef.current;
    const scaleX = image.naturalWidth / image.width;
    const scaleY = image.naturalHeight / image.height;
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(completedCrop.width * scaleX));
    canvas.height = Math.max(1, Math.round(completedCrop.height * scaleY));
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(
      image,
      completedCrop.x * scaleX, completedCrop.y * scaleY, completedCrop.width * scaleX, completedCrop.height * scaleY,
      0, 0, canvas.width, canvas.height
    );
    onAdd(canvas.toDataURL('image/png'));
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/50" onClick={onClose}>
      <div
        className="bg-appSurface rounded-lg shadow-2xl w-full max-w-2xl max-h-[85vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-5 py-4 border-b border-appBorder">
          <h3 className="text-sm font-bold text-appTextPrimary">{mode === 'signature' ? 'Add signature' : 'Upload image'}</h3>
          <button onClick={onClose} className="p-1 rounded hover:bg-appBg text-appTextSecondary hover:text-appTextPrimary">
            <X size={18} />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {mode === 'signature' && (
            <div className="flex items-center gap-1 border border-appBorder rounded-full p-1 w-fit">
              <button
                onClick={() => setSubMode('upload')}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold flex items-center gap-1.5 transition-colors ${subMode === 'upload' ? 'bg-brand-500 text-white' : 'text-appTextSecondary hover:text-appTextPrimary'}`}
              >
                <ImagePlus size={13} /> Upload
              </button>
              <button
                onClick={() => setSubMode('draw')}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold flex items-center gap-1.5 transition-colors ${subMode === 'draw' ? 'bg-brand-500 text-white' : 'text-appTextSecondary hover:text-appTextPrimary'}`}
              >
                <PenTool size={13} /> Draw
              </button>
            </div>
          )}

          {mode === 'signature' && subMode === 'draw' ? (
            <SignaturePad onAdd={(dataUrl) => { onAdd(dataUrl); onClose(); }} />
          ) : !pendingSrc ? (
            <div
              onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
              onDragLeave={() => setIsDragOver(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragOver(false); loadFile(e.dataTransfer.files?.[0]); }}
              onClick={() => fileInputRef.current?.click()}
              role="button"
              tabIndex={0}
              className={`cursor-pointer flex flex-col items-center justify-center gap-2 py-16 rounded-lg border-2 border-dashed transition-colors ${
                isDragOver ? 'border-brand-500 bg-brand-500/5' : 'border-appBorder hover:border-brand-400/60'
              }`}
            >
              <Upload size={28} className="text-appTextSecondary" />
              <p className="text-sm text-appTextSecondary">
                <span className="text-brand-500 font-semibold">Choose a file</span> or drag it here
              </p>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => { loadFile(e.target.files?.[0]); e.target.value = ''; }}
              />
            </div>
          ) : (
            <div className="space-y-3">
              <div className="bg-appBg border border-appBorder rounded-lg p-3 flex justify-center">
                <ReactCrop crop={crop} onChange={(_, pc) => setCrop(pc)} onComplete={(c) => setCompletedCrop(c)}>
                  {/* eslint-disable-next-line jsx-a11y/alt-text */}
                  <img ref={imgRef} src={pendingSrc} onLoad={handleImageLoad} style={{ maxHeight: 420, display: 'block' }} />
                </ReactCrop>
              </div>
              <div className="flex items-center justify-between gap-3">
                <p className="text-xs text-appTextSecondary flex-1">Drag the corners/edges to adjust the crop area.</p>
                <button
                  onClick={handleRemoveBackground}
                  disabled={removingBg}
                  className="flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-appBorder text-xs font-semibold text-appTextPrimary hover:border-brand-500 hover:text-brand-500 disabled:opacity-50 transition-colors"
                  title="Removes a plain/uniform background (e.g. white paper) — not full AI subject segmentation"
                >
                  <Wand2 size={13} />
                  {removingBg ? 'Removing…' : bgRemoved ? 'Background removed' : 'Remove background'}
                </button>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => { setPendingSrc(null); setCrop(undefined); setBgRemoved(false); }}
                  className="flex-1 py-2 text-sm font-semibold rounded-[4px] border border-appBorder text-appTextSecondary hover:text-appTextPrimary hover:bg-appBg transition-colors"
                >
                  Back
                </button>
                <button
                  onClick={handleAdd}
                  disabled={!completedCrop?.width}
                  className="flex-1 py-2 text-sm font-semibold rounded-[4px] bg-brand-500 text-white hover:bg-brand-600 disabled:opacity-50 transition-colors"
                >
                  Add
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AssetModal;

