            <div>
              <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1.5">Table styles</span>
              <div className="grid grid-cols-4 gap-1.5">
                {TABLE_STYLE_PRESETS.map((preset) => (
