import React, { useEffect, useRef, useState } from 'react';
import type { InvoiceElement } from '../../types/canvasElement';
import type { CanvasTool } from '../../store/documentStore';

interface SelectOptions {
  additive?: boolean;
}

// row: -1 means the header row.
export interface TableCellRef {
  elId: string;
  row: number;
  col: number;
}

interface InvoiceCanvasProps {
  elements: InvoiceElement[];
  selectedElementId: string | null;
  selectedElementIds: string[];
  activeTool: CanvasTool;
  zoom: number;
  pageWidth: number;
  pageHeight: number;
  pageBackgroundColor: string;
  showGrid: boolean;
  pageIndex?: number;
  pageOffsetY?: number;
  onSelect: (id: string | null, options?: SelectOptions) => void;
  onSelectMany: (ids: string[]) => void;
  onSelectPage: () => void;
  onUpdate: (id: string, patch: Partial<InvoiceElement>) => void;
  onUpdateMany: (ids: string[], patch: Partial<InvoiceElement> | ((id: string) => Partial<InvoiceElement>)) => void;
  onAddElement: (el: InvoiceElement) => void;
  onCheckpoint: () => void;
  // Right-click on an element — selects it first if it wasn't already part
  // of the selection (matching standard right-click behavior everywhere),
  // then reports the cursor position for BuilderPage to anchor a context
  // menu at. `cell` is set when the right-click landed inside a specific
  // table cell, so the menu can offer row/column operations.
  onContextMenu?: (e: React.MouseEvent, elementId: string, cell?: TableCellRef) => void;
  // A single click on a table cell selects just that cell (distinct from
  // selecting the whole table) — controlled from BuilderPage so the
  // inspector panel can show per-cell formatting controls for it.
  selectedCell: TableCellRef | null;
  onSelectCell: (cell: TableCellRef | null) => void;
}

let addCounter = 0;

// Checks a moving edge (left/center/right of `pos`+`size`) against a list of
// target coordinates (other elements' edges/centers, the page's bounds/
// center) and returns the smallest adjustment that would snap it exactly
// onto the closest target within `threshold`, plus where to draw the guide
// line — or null if nothing is close enough to snap to.
function findSnap(pos: number, size: number, targets: number[], threshold: number): { offset: number; guide: number } | null {
  const left = pos;
  const center = pos + size / 2;
  const right = pos + size;
  let best: { diff: number; offset: number; guide: number } | null = null;
  for (const t of targets) {
    const dLeft = Math.abs(left - t);
    const dCenter = Math.abs(center - t);
    const dRight = Math.abs(right - t);
    if (dLeft < threshold && (!best || dLeft < best.diff)) best = { diff: dLeft, offset: t - left, guide: t };
    if (dCenter < threshold && (!best || dCenter < best.diff)) best = { diff: dCenter, offset: t - center, guide: t };
    if (dRight < threshold && (!best || dRight < best.diff)) best = { diff: dRight, offset: t - right, guide: t };
  }
  return best ? { offset: best.offset, guide: best.guide } : null;
}

// Elements render absolutely positioned inside a fixed 595x842 page — every
// text/shape from the source template is independently selectable, movable
// (drag anywhere on the page, no opt-in needed) and resizable, matching a
// Figma-style canvas rather than a static preview.
const InvoiceCanvas: React.FC<InvoiceCanvasProps> = ({
  elements,
  selectedElementId,
  selectedElementIds,
  activeTool,
  zoom,
  pageWidth,
  pageHeight,
  pageBackgroundColor,
  showGrid,
  pageIndex = 0,
  pageOffsetY = 0,
  onSelect,
  onSelectMany,
  onSelectPage,
  onUpdate,
  onUpdateMany,
  onAddElement,
  onCheckpoint,
  onContextMenu,
  selectedCell,
  onSelectCell,
}) => {
  // Group-drag holds the starting position of every element being moved
  // together (just one, most of the time) so each keeps its own offset.
  // `checkpointed` defers the undo-history snapshot to the first actual
  // pointermove of the gesture, so a plain click-without-drag never pushes
  // a no-op undo step.
  const dragRef = useRef<{ startX: number; startY: number; origins: Record<string, { x: number; y: number }>; checkpointed: boolean } | null>(null);
  const resizeRef = useRef<{ id: string; corner: string; startX: number; startY: number; orig: { x: number; y: number; w: number; h: number }; checkpointed: boolean } | null>(null);
  const rotateRef = useRef<{ id: string; checkpointed: boolean } | null>(null);
  // Marquee/rubber-band selection — dragging from empty canvas space draws a
  // selection box; anything it intersects becomes the new selection on
  // release. Kept in a ref (not just state) so the pointerup handler always
  // sees the latest box even if a state update hasn't flushed yet.
  const marqueeRef = useRef<{ startX: number; startY: number; curX: number; curY: number; additive: boolean } | null>(null);
  const [marqueeBox, setMarqueeBox] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  // Canva/Figma-style alignment guides — only meaningful for a single-
  // element drag (see below), cleared whenever the gesture ends.
  const [snapLines, setSnapLines] = useState<{ x: number | null; y: number | null }>({ x: null, y: null });
  // Refs mirroring the latest elements/selection props — the window-level
  // pointerup/pointercancel safety-net listeners below are attached once
  // ([] deps) so their closure over `endInteraction` can go stale; reading
  // through refs instead keeps marquee finalization correct even there.
  const elementsRef = useRef(elements);
  elementsRef.current = elements;
  const selectedElementIdsRef = useRef(selectedElementIds);
  selectedElementIdsRef.current = selectedElementIds;
  // Pointer capture is set on this stable root, never on the individual
  // text/shape node being dragged — capturing on a per-element node that
  // React can re-render/replace mid-drag (e.g. a contentEditable div
  // toggling editability the instant it becomes selected) can leave the
  // capture stuck with no further pointerup ever delivered. When that
  // happens the browser silently routes *every* click anywhere on the page
  // to the now-detached element until reload, which reads as "the whole
  // app stopped responding to clicks."
  const rootRef = useRef<HTMLDivElement>(null);
  const scale = zoom / 100;

  const endInteraction = (pointerId?: number) => {
    dragRef.current = null;
    resizeRef.current = null;
    rotateRef.current = null;
    setSnapLines({ x: null, y: null });
    if (marqueeRef.current) {
      const { startX, startY, curX, curY, additive } = marqueeRef.current;
      const bx = Math.min(startX, curX);
      const by = Math.min(startY, curY);
      const bw = Math.abs(curX - startX);
      const bh = Math.abs(curY - startY);
      marqueeRef.current = null;
      setMarqueeBox(null);
      // A near-zero box means this was really just a click on empty canvas
      // — clear the selection (unless it was a shift/ctrl/cmd click, which
      // shouldn't wipe out an existing selection over nothing).
      if (bw < 3 && bh < 3) {
        if (!additive) onSelect(null);
      } else {
        const hitIds = elementsRef.current
          .filter((el) => el.x < bx + bw && el.x + el.w > bx && el.y < by + bh && el.y + el.h > by)
          .map((el) => el.id);
        onSelectMany(additive ? Array.from(new Set([...selectedElementIdsRef.current, ...hitIds])) : hitIds);
      }
    }
    if (pointerId !== undefined && rootRef.current?.hasPointerCapture?.(pointerId)) {
      rootRef.current.releasePointerCapture(pointerId);
    }
  };

  // Safety net: if a pointerup/pointercancel never bubbles through the
  // canvas itself (capture lost, element removed, browser quirk), this
  // still fires and clears the drag/resize state so it can't get stuck.
  useEffect(() => {
    const forceEnd = (e: PointerEvent) => endInteraction(e.pointerId);
    window.addEventListener('pointerup', forceEnd);
    window.addEventListener('pointercancel', forceEnd);
    return () => {
      window.removeEventListener('pointerup', forceEnd);
      window.removeEventListener('pointercancel', forceEnd);
    };
  }, []);

  const handlePointerDownOnElement = (e: React.PointerEvent, el: InvoiceElement) => {
    if (activeTool !== 'select' || el.locked) return;
    e.stopPropagation();

    // Alt+drag duplicates the element in place and immediately drags the
    // copy, leaving the original untouched — matches Canva/Figma. The
    // store's addElement() self-checkpoints history, so there's no separate
    // onCheckpoint() call needed here.
    if (e.altKey) {
      addCounter += 1;
      const newId = `custom_${Date.now()}_${addCounter}`;
      onAddElement({ ...el, id: newId } as InvoiceElement);
      e.currentTarget.setPointerCapture(e.pointerId);
      dragRef.current = { startX: e.clientX, startY: e.clientY, origins: { [newId]: { x: el.x, y: el.y } }, checkpointed: true };
      return;
    }

    // Shift+click, Ctrl+click (Windows/Linux) and Cmd+click (Mac) all add
    // to / toggle the selection instead of replacing it.
    const additive = e.shiftKey || e.ctrlKey || e.metaKey;
    const alreadyInGroup = selectedElementIds.includes(el.id);
    // A persisted group (via "Group selection") always selects as a whole —
    // distinct from the transient multi-select below, which only stays
    // together for as long as it's already the active selection.
    const persistedGroupIds = el.groupId ? elements.filter((other) => other.groupId === el.groupId).map((other) => other.id) : [el.id];
    if (additive) {
      onSelect(el.id, { additive: true });
    } else if (!alreadyInGroup) {
      // Plain click on an element outside the current multi-selection
      // replaces the selection with just this one — or its whole persisted
      // group, if it belongs to one.
      if (persistedGroupIds.length > 1) onSelectMany(persistedGroupIds);
      else onSelect(el.id);
    }
    // else: plain click on an element that's already part of a multi-select
    // — keep the whole group selected so the drag below moves all of them.

    // Capture on the actual pressed element (e.currentTarget), not a
    // separate stable node — the browser only synthesizes click/dblclick
    // when pointerdown and pointerup resolve to the same element, and
    // capturing elsewhere (e.g. the canvas root) silently breaks that,
    // which is why double-click-to-edit stopped firing when this captured
    // on a shared ref instead. The window-level pointerup/pointercancel
    // listeners below are what actually guard against a stuck capture.
    e.currentTarget.setPointerCapture(e.pointerId);

    const groupIds = additive
      ? [el.id]
      : alreadyInGroup && selectedElementIds.length > 1
      ? selectedElementIds
      : persistedGroupIds;
    const origins: Record<string, { x: number; y: number }> = {};
    for (const id of groupIds) {
      const found = elements.find((candidate) => candidate.id === id);
      if (found) origins[id] = { x: found.x, y: found.y };
    }
    dragRef.current = { startX: e.clientX, startY: e.clientY, origins, checkpointed: false };
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    // If we think a drag/resize is active but the primary button isn't
    // actually held anymore, the mouseup was missed somewhere — bail out
    // instead of continuing to apply position updates from a stale ref.
    if ((dragRef.current || resizeRef.current || rotateRef.current || marqueeRef.current) && !(e.buttons & 1)) {
      endInteraction(e.pointerId);
      return;
    }
    if (dragRef.current) {
      // Checkpoint once, on the first real movement of the gesture — not
      // on pointerdown — so a plain click-without-drag never pushes a
      // no-op undo step.
      if (!dragRef.current.checkpointed) {
        onCheckpoint();
        dragRef.current.checkpointed = true;
      }
      const { startX, startY, origins } = dragRef.current;
      let dx = (e.clientX - startX) / scale;
      let dy = (e.clientY - startY) / scale;
      // Shift constrains the drag to a straight horizontal or vertical line
      // (matches Canva/Figma) — lock whichever axis has moved less.
      if (e.shiftKey) {
        if (Math.abs(dx) > Math.abs(dy)) dy = 0;
        else dx = 0;
      }
      const ids = Object.keys(origins);
      if (ids.length === 1) {
        const [id] = ids;
        const el = elementsRef.current.find((candidate) => candidate.id === id);
        let newX = Math.round(origins[id].x + dx);
        let newY = Math.round(origins[id].y + dy);
        let guideX: number | null = null;
        let guideY: number | null = null;
        if (el) {
          // ~6 screen pixels of "magnetism" regardless of zoom level — the
          // threshold is expressed in page-space units, so it has to grow
          // as the page shrinks on screen to still feel like 6px.
          const threshold = 6 / scale;
          const xTargets = [0, pageWidth / 2, pageWidth];
          const yTargets = [pageOffsetY, pageOffsetY + pageHeight / 2, pageOffsetY + pageHeight];
          for (const other of elementsRef.current) {
            if (other.id === id) continue;
            xTargets.push(other.x, other.x + other.w / 2, other.x + other.w);
            yTargets.push(other.y, other.y + other.h / 2, other.y + other.h);
          }
          const snapX = findSnap(newX, el.w, xTargets, threshold);
          if (snapX) { newX += Math.round(snapX.offset); guideX = snapX.guide; }
          const snapY = findSnap(newY, el.h, yTargets, threshold);
          if (snapY) { newY += Math.round(snapY.offset); guideY = snapY.guide; }
        }
        setSnapLines({ x: guideX, y: guideY });
        onUpdate(id, { x: newX, y: newY });
      } else if (ids.length > 1) {
        if (snapLines.x !== null || snapLines.y !== null) setSnapLines({ x: null, y: null });
        onUpdateMany(ids, (id) => ({ x: Math.round(origins[id].x + dx), y: Math.round(origins[id].y + dy) }));
      }
    } else if (resizeRef.current) {
      if (!resizeRef.current.checkpointed) {
        onCheckpoint();
        resizeRef.current.checkpointed = true;
      }
      const { id, corner, startX, startY, orig } = resizeRef.current;
      const dx = (e.clientX - startX) / scale;
      const dy = (e.clientY - startY) / scale;
      const patch: Partial<InvoiceElement> = {};
      // Shift keeps the element's original aspect ratio while resizing —
      // the horizontal delta drives the size, height follows proportionally.
      if (e.shiftKey && orig.w > 0 && orig.h > 0) {
        const ratio = orig.w / orig.h;
        const rawW = orig.w + (corner.includes('w') ? -dx : dx);
        const newW = Math.max(8, rawW);
        const newH = Math.max(8, newW / ratio);
        patch.w = Math.round(newW);
        patch.h = Math.round(newH);
        if (corner.includes('w')) patch.x = Math.round(orig.x + (orig.w - newW));
        if (corner.includes('n')) patch.y = Math.round(orig.y + (orig.h - newH));
      } else {
        if (corner.includes('e')) patch.w = Math.max(8, Math.round(orig.w + dx));
        if (corner.includes('s')) patch.h = Math.max(8, Math.round(orig.h + dy));
        if (corner.includes('w')) {
          patch.w = Math.max(8, Math.round(orig.w - dx));
          patch.x = Math.round(orig.x + dx);
        }
        if (corner.includes('n')) {
          patch.h = Math.max(8, Math.round(orig.h - dy));
          patch.y = Math.round(orig.y + dy);
        }
      }
      onUpdate(id, patch);
    } else if (rotateRef.current) {
      if (!rotateRef.current.checkpointed) {
        onCheckpoint();
        rotateRef.current.checkpointed = true;
      }
      const { id } = rotateRef.current;
      const el = elementsRef.current.find((candidate) => candidate.id === id);
      if (el && rootRef.current) {
        const rootRect = rootRef.current.getBoundingClientRect();
        // Element center in screen space — the handle sits directly "up"
        // from this point in the element's own (possibly already rotated)
        // local space, so computing the absolute angle from center to
        // pointer and using it directly as the new rotation is correct
        // regardless of the current rotation value.
        // el.x/el.y are absolute page-space coordinates (consistent across
        // every page), but rootRect is THIS page's own bounding box — el.y
        // has to be brought back into this page's local space the same way
        // the render loop does (elTop = el.y - pageOffsetY) before scaling,
        // or the computed center drifts further from the real one on every
        // page after the first, making the rotate handle feel disconnected
        // from the cursor on page 2+.
        const cx = rootRect.left + (el.x + el.w / 2) * scale;
        const cy = rootRect.top + (el.y - pageOffsetY + el.h / 2) * scale;
        let deg = (Math.atan2(e.clientY - cy, e.clientX - cx) * 180) / Math.PI + 90;
        // Shift snaps to 15° increments, matching Canva/Figma/PowerPoint.
        if (e.shiftKey) deg = Math.round(deg / 15) * 15;
        onUpdate(id, { rotation: Math.round(deg) });
      }
    } else if (marqueeRef.current) {
      const rect = rootRef.current!.getBoundingClientRect();
      marqueeRef.current.curX = (e.clientX - rect.left) / scale;
      marqueeRef.current.curY = (e.clientY - rect.top) / scale;
      const { startX, startY, curX, curY } = marqueeRef.current;
      setMarqueeBox({ x: Math.min(startX, curX), y: Math.min(startY, curY), w: Math.abs(curX - startX), h: Math.abs(curY - startY) });
    }
  };

  const handleResizeStart = (e: React.PointerEvent, el: InvoiceElement, corner: string) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture(e.pointerId);
    resizeRef.current = { id: el.id, corner, startX: e.clientX, startY: e.clientY, orig: { x: el.x, y: el.y, w: el.w, h: el.h }, checkpointed: false };
  };

  const handleRotateStart = (e: React.PointerEvent, el: InvoiceElement) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture(e.pointerId);
    rotateRef.current = { id: el.id, checkpointed: false };
  };

  // Pointerdown on the canvas root itself (children stopPropagation in
  // handlePointerDownOnElement, so this only fires for genuinely empty
  // canvas) starts a marquee/rubber-band selection when the Select tool is
  // active — matches Figma/Canva drag-to-select.
  const handleRootPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (activeTool !== 'select') return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale;
    const y = (e.clientY - rect.top) / scale + pageOffsetY;
    marqueeRef.current = { startX: x, startY: y, curX: x, curY: y, additive: e.shiftKey || e.ctrlKey || e.metaKey };
    setMarqueeBox({ x, y, w: 0, h: 0 });
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLDivElement>) => {
    // Marquee-select already handles selection on pointerup; a plain click
    // on the Select tool with no marquee drawn (bw/bh ~0) is handled inside
    // endInteraction instead of here, so don't double-deselect.
    if (activeTool === 'select') return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = Math.round((e.clientX - rect.left) / scale);
    const y = Math.round((e.clientY - rect.top) / scale + pageOffsetY);
    addCounter += 1;
    const id = `custom_${Date.now()}_${addCounter}`;

    if (activeTool === 'text') {
      onAddElement({ id, type: 'text', x, y, w: 160, h: 24, text: 'Text', fontSize: 14, fontWeight: 400, color: '#1a1c21', align: 'left', section: 'custom', zIndex: 10 });
    } else if (activeTool === 'rect') {
      onAddElement({ id, type: 'rect', x, y, w: 120, h: 80, fill: '#d9dee6', section: 'custom', zIndex: 10 });
    } else if (activeTool === 'ellipse') {
      onAddElement({ id, type: 'ellipse', x, y, w: 100, h: 100, fill: '#d9dee6', section: 'custom', zIndex: 10 });
    } else if (activeTool === 'line') {
      onAddElement({ id, type: 'line', x, y, w: 150, h: 10, fill: '#1a1c21', strokeWidth: 2, lineStyle: 'solid', section: 'custom', zIndex: 10 });
    }
  };

  const handleTextEdit = (el: InvoiceElement, value: string) => {
    onUpdate(el.id, { text: value } as Partial<InvoiceElement>);
  };

  // Single click selects (and can drag); double-click enters text-edit mode.
  // Keeping these separate means clicking-and-dragging a text element never
  // fights with placing a cursor inside it, and vice versa.
  const [editingId, setEditingId] = useState<string | null>(null);

  // Selecting a different element (or deselecting) always exits edit mode —
  // otherwise a stray contentEditable could stay active on an element that
  // isn't even selected anymore.
  useEffect(() => {
    if (editingId && editingId !== selectedElementId) setEditingId(null);
  }, [selectedElementId, editingId]);

  const handleTextDoubleClick = (e: React.MouseEvent, el: InvoiceElement) => {
    if (activeTool !== 'select') return;
    e.stopPropagation();
    onSelect(el.id);
    setEditingId(el.id);
    const target = e.currentTarget as HTMLElement;
    // Focus synchronously — contentEditable only takes effect on the next
    // React render, so flip it on the DOM directly first or the browser
    // won't treat the element as focusable/editable yet.
    target.contentEditable = 'true';
    target.focus();
    const range = document.createRange();
    range.selectNodeContents(target);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
  };

  // Table cell editing — separate from editingId (which is scoped to a
  // whole TextElement's body) since a table needs to track WHICH cell.
  // row: -1 means the header row.
  const [editingCell, setEditingCell] = useState<{ elId: string; row: number; col: number } | null>(null);
  useEffect(() => {
    if (editingCell && editingCell.elId !== selectedElementId) setEditingCell(null);
  }, [selectedElementId, editingCell]);

  const handleCellDoubleClick = (e: React.MouseEvent, elId: string, row: number, col: number) => {
    if (activeTool !== 'select') return;
    e.stopPropagation();
    onSelect(elId);
    setEditingCell({ elId, row, col });
    const target = e.currentTarget as HTMLElement;
    target.contentEditable = 'true';
    target.focus();
    const range = document.createRange();
    range.selectNodeContents(target);
    const sel = window.getSelection();
    sel?.removeAllRanges();
    sel?.addRange(range);
  };

  const sorted = [...elements].sort((a, b) => a.zIndex - b.zIndex);

  return (
    <div
      ref={rootRef}
      className="relative select-none"
      style={{ width: pageWidth, height: pageHeight, backgroundColor: pageBackgroundColor, cursor: activeTool === 'select' ? 'default' : 'crosshair' }}
      onPointerDown={handleRootPointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(e) => endInteraction(e.pointerId)}
      onPointerCancel={(e) => endInteraction(e.pointerId)}
      onLostPointerCapture={(e) => endInteraction(e.pointerId)}
      onClick={handleCanvasClick}
      onDoubleClick={(e) => { if (activeTool === 'select' && e.target === e.currentTarget) onSelectPage(); }}
      id={`invoice-canvas-page-${pageIndex}`}
      data-page-index={pageIndex}
    >
      {/* Toggleable background grid — purely visual, no snapping tied to
          it (snapping instead targets other elements' edges/centers and
          the page's own bounds/center, which is the more useful reference
          when actually laying things out). */}
      {showGrid && (
        <div
          className="pointer-events-none absolute inset-0"
          style={{
            backgroundImage: 'linear-gradient(to right, rgba(0,0,0,0.06) 1px, transparent 1px), linear-gradient(to bottom, rgba(0,0,0,0.06) 1px, transparent 1px)',
            backgroundSize: '20px 20px',
          }}
        />
      )}
      {snapLines.x !== null && (
        <div className="pointer-events-none absolute top-0 bottom-0 w-px bg-pink-500" style={{ left: snapLines.x }} />
      )}
      {snapLines.y !== null && snapLines.y >= pageOffsetY && snapLines.y <= pageOffsetY + pageHeight && (
        <div className="pointer-events-none absolute left-0 right-0 h-px bg-pink-500" style={{ top: snapLines.y - pageOffsetY }} />
      )}
      {sorted.map((el) => {
        if (el.hidden) return null;
        const elTop = el.y - pageOffsetY;
        const elHeight = el.h || 20;
        if (elTop + elHeight < -10 || elTop > pageHeight + 10) return null;

        const isSelected = selectedElementIds.includes(el.id);
        const isPrimarySelection = el.id === selectedElementId;
        // Drop shadow — box-shadow for filled shapes/images (needs an opaque
        // shape to read correctly), text-shadow for text (a box-shadow on a
        // transparent-background text wrapper would just outline empty
        // space instead of hugging the glyphs).
        const shadowValue = el.shadowEnabled
          ? `${el.shadowOffsetX ?? 0}px ${el.shadowOffsetY ?? 4}px ${el.shadowBlur ?? 8}px ${el.shadowColor ?? 'rgba(0,0,0,0.35)'}`
          : undefined;
        const commonStyle: React.CSSProperties = {
          position: 'absolute',
          left: el.x,
          top: elTop,
          width: el.w,
          minHeight: el.h,
          height: el.type === 'text' ? 'auto' : el.h,
          opacity: el.opacity ?? 1,
          boxShadow: el.type !== 'text' ? shadowValue : undefined,
          // Rotate first, then flip — order matters for the combined
          // transform to look right when both are set, and matches how
          // Figma/Canva apply the two together.
          transform: [
            el.rotation ? `rotate(${el.rotation}deg)` : '',
            el.flipH ? 'scaleX(-1)' : '',
            el.flipV ? 'scaleY(-1)' : '',
          ].filter(Boolean).join(' ') || undefined,
        };

        let body: React.ReactNode;
        if (el.type === 'text') {
          const isEditing = el.id === editingId;
          body = (
            <div
              contentEditable={isEditing}
              suppressContentEditableWarning
              onDoubleClick={(e) => handleTextDoubleClick(e, el)}
              onBlur={(e) => {
                if (isEditing) {
                  handleTextEdit(el, e.currentTarget.textContent || '');
                  setEditingId(null);
                }
              }}
              onPointerDown={(e) => { if (!isEditing) handlePointerDownOnElement(e, el); else e.stopPropagation(); }}
              style={{
                width: '100%',
                minHeight: '100%',
                fontSize: el.fontSize,
                fontWeight: el.fontWeight,
                fontStyle: el.italic ? 'italic' : 'normal',
                textDecoration: [el.underline && 'underline', el.strikethrough && 'line-through'].filter(Boolean).join(' ') || 'none',
                color: el.color,
                textAlign: el.align,
                fontFamily: el.fontFamily || "'Inter', sans-serif",
                lineHeight: el.lineHeight ?? 1.35,
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
                boxSizing: 'border-box',
                textShadow: shadowValue,
                border: el.stroke ? `${el.strokeWidth ?? 1}px solid ${el.stroke}` : undefined,
                outline: isEditing ? '1px dashed currentColor' : 'none',
                cursor: isEditing ? 'text' : activeTool === 'select' ? 'move' : 'inherit',
              }}
            >
              {el.text}
            </div>
          );
        } else if (el.type === 'rect') {
          body = (
            <div
              onPointerDown={(e) => handlePointerDownOnElement(e, el)}
              style={{ width: '100%', height: '100%', background: el.fill, border: el.stroke ? `${el.strokeWidth ?? 1}px solid ${el.stroke}` : undefined, borderRadius: el.radius ?? 0, cursor: activeTool === 'select' ? 'move' : 'inherit' }}
            />
          );
        } else if (el.type === 'ellipse') {
          body = (
            <div
              onPointerDown={(e) => handlePointerDownOnElement(e, el)}
              style={{ width: '100%', height: '100%', background: el.fill, border: el.stroke ? `${el.strokeWidth ?? 1}px solid ${el.stroke}` : undefined, borderRadius: '50%', cursor: activeTool === 'select' ? 'move' : 'inherit' }}
            />
          );
        } else if (el.type === 'line') {
          const weight = el.strokeWidth ?? 2;
          const lineStyle = el.lineStyle ?? 'solid';
          // A line's own box can be wide-and-flat (a horizontal rule) or
          // tall-and-thin (a vertical divider, e.g. a column separator) —
          // orient the drawn stroke to match, otherwise a vertical box only
          // ever paints a horizontal border-top pinned to its own vertical
          // center, collapsing to an invisible dot instead of a rule.
          const isVertical = el.h > el.w;
          // solid/dashed/dotted are native CSS border-style keywords —
          // render those via border-top/border-left. 'long-dash' and
          // 'dash-dot' have no native keyword, so those two are drawn with a
          // repeating background gradient instead, giving control over
          // exact dash/gap lengths that a border can't express.
          const lineInnerStyle: React.CSSProperties =
            lineStyle === 'long-dash'
              ? isVertical
                ? { height: '100%', width: weight, backgroundImage: `repeating-linear-gradient(to bottom, ${el.fill} 0, ${el.fill} ${weight * 6}px, transparent ${weight * 6}px, transparent ${weight * 9}px)` }
                : { width: '100%', height: weight, backgroundImage: `repeating-linear-gradient(to right, ${el.fill} 0, ${el.fill} ${weight * 6}px, transparent ${weight * 6}px, transparent ${weight * 9}px)` }
              : lineStyle === 'dash-dot'
              ? isVertical
                ? { height: '100%', width: weight, backgroundImage: `repeating-linear-gradient(to bottom, ${el.fill} 0, ${el.fill} ${weight * 4}px, transparent ${weight * 4}px, transparent ${weight * 6}px, ${el.fill} ${weight * 6}px, ${el.fill} ${weight * 7}px, transparent ${weight * 7}px, transparent ${weight * 9}px)` }
                : { width: '100%', height: weight, backgroundImage: `repeating-linear-gradient(to right, ${el.fill} 0, ${el.fill} ${weight * 4}px, transparent ${weight * 4}px, transparent ${weight * 6}px, ${el.fill} ${weight * 6}px, ${el.fill} ${weight * 7}px, transparent ${weight * 7}px, transparent ${weight * 9}px)` }
              : isVertical
              ? { height: '100%', borderLeft: `${weight}px ${lineStyle} ${el.fill}` }
              : { width: '100%', borderTop: `${weight}px ${lineStyle} ${el.fill}` };
          // Rendered via border/background rather than a filled block so
          // dashed/dotted/etc. lines are possible — the bounding box stays a
          // comfortable drag/resize target even when the line itself is thin.
          body = (
            <div
              onPointerDown={(e) => handlePointerDownOnElement(e, el)}
              style={{
                width: '100%',
                height: '100%',
                display: 'flex',
                alignItems: isVertical ? 'stretch' : 'center',
                justifyContent: isVertical ? 'center' : 'flex-start',
                cursor: activeTool === 'select' ? 'move' : 'inherit',
              }}
            >
              <div style={lineInnerStyle} />
            </div>
          );
        } else if (el.type === 'image') {
          // draggable={false} — browsers make <img> elements natively
          // HTML5-draggable by default, which hijacks the very first
          // pointermove into the browser's own "ghost image" drag instead
          // of our custom pointer-based drag logic, breaking dragging for
          // image/signature elements specifically (text/shapes don't have
          // this native behavior, which is why only images looked broken).
          body = (
            <img
              src={el.src}
              alt=""
              draggable={false}
              onPointerDown={(e) => handlePointerDownOnElement(e, el)}
              style={{ width: '100%', height: '100%', objectFit: 'contain', cursor: activeTool === 'select' ? 'move' : 'inherit' }}
            />
          );
        } else if (el.type === 'table') {
          const isEditingCell = (row: number, col: number) =>
            !!editingCell && editingCell.elId === el.id && editingCell.row === row && editingCell.col === col;
          const isSelectedCell = (row: number, col: number) =>
            !!selectedCell && selectedCell.elId === el.id && selectedCell.row === row && selectedCell.col === col;
          const cellFormat = (row: number, col: number) => el.cellFormats?.[`${row === -1 ? 'h' : row}-${col}`];
          const commitCell = (row: number, col: number, value: string) => {
            if (row === -1) {
              onUpdate(el.id, { columns: el.columns.map((c, i) => (i === col ? { ...c, label: value } : c)) } as Partial<InvoiceElement>);
            } else {
              onUpdate(el.id, { rows: el.rows.map((r, ri) => (ri === row ? r.map((cell, ci) => (ci === col ? value : cell)) : r)) } as Partial<InvoiceElement>);
            }
          };
          const justify = (align?: 'left' | 'center' | 'right') => (align === 'right' ? 'flex-end' : align === 'center' ? 'center' : 'flex-start');
          const handleCellClick = (e: React.MouseEvent, row: number, col: number) => {
            if (activeTool !== 'select' || isEditingCell(row, col)) return;
            e.stopPropagation();
            onSelect(el.id);
            onSelectCell({ elId: el.id, row, col });
          };
          const handleCellContextMenu = (e: React.MouseEvent, row: number, col: number) => {
            if (activeTool !== 'select' || !onContextMenu) return;
            e.preventDefault();
            e.stopPropagation();
            if (!selectedElementIds.includes(el.id)) onSelect(el.id);
            onSelectCell({ elId: el.id, row, col });
            onContextMenu(e, el.id, { elId: el.id, row, col });
          };
          // Cell-level formatting overrides the table's own defaults —
          // most cells never get one, so this stays cheap per-render.
          const cellStyle = (row: number, col: number, base: React.CSSProperties): React.CSSProperties => {
            const fmt = cellFormat(row, col);
            if (!fmt) return base;
            return {
              ...base,
              fontWeight: fmt.bold !== undefined ? (fmt.bold ? 700 : 400) : base.fontWeight,
              fontStyle: fmt.italic ? 'italic' : base.fontStyle,
              textDecoration: fmt.underline ? 'underline' : base.textDecoration,
              color: fmt.color || base.color,
              fontSize: fmt.fontSize ?? base.fontSize,
              justifyContent: fmt.align ? justify(fmt.align) : base.justifyContent,
            };
          };
          body = (
            <div
              onPointerDown={(e) => { if (!editingCell || editingCell.elId !== el.id) handlePointerDownOnElement(e, el); else e.stopPropagation(); }}
              style={{
                width: '100%', height: '100%', display: 'flex', flexDirection: 'column', boxSizing: 'border-box',
                border: `1px solid ${el.borderColor}`, fontSize: el.fontSize, fontFamily: "'Inter', sans-serif",
                cursor: activeTool === 'select' ? 'move' : 'inherit', overflow: 'hidden',
              }}
            >
              <div style={{ display: 'flex', height: el.headerHeight, background: el.headerBg, flexShrink: 0 }}>
                {el.columns.map((col, ci) => (
                  <div
                    key={ci}
                    contentEditable={isEditingCell(-1, ci)}
                    suppressContentEditableWarning
                    onClick={(e) => handleCellClick(e, -1, ci)}
                    onDoubleClick={(e) => handleCellDoubleClick(e, el.id, -1, ci)}
                    onContextMenu={(e) => handleCellContextMenu(e, -1, ci)}
                    onBlur={(e) => { if (isEditingCell(-1, ci)) { commitCell(-1, ci, e.currentTarget.textContent || ''); setEditingCell(null); } }}
                    style={cellStyle(-1, ci, {
                      width: col.width, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: justify(col.align),
                      padding: '0 6px', fontWeight: 700, color: el.headerColor,
                      borderRight: ci < el.columns.length - 1 ? `1px solid ${el.borderColor}` : undefined,
                      outline: isEditingCell(-1, ci) ? '1px dashed currentColor' : isSelectedCell(-1, ci) ? '1.5px solid #6d28d9' : 'none',
                      outlineOffset: isSelectedCell(-1, ci) ? -1.5 : undefined,
                      overflow: 'hidden', whiteSpace: 'nowrap',
                    })}
                  >
                    {col.label}
                  </div>
                ))}
              </div>
              {el.rows.map((row, ri) => (
                <div
                  key={ri}
                  style={{
                    display: 'flex', height: el.rowHeight, borderTop: `1px solid ${el.borderColor}`, flexShrink: 0,
                    background: el.rowStripeColor && ri % 2 === 1 ? el.rowStripeColor : undefined,
                  }}
                >
                  {row.map((cell, ci) => (
                    <div
                      key={ci}
                      contentEditable={isEditingCell(ri, ci)}
                      suppressContentEditableWarning
                      onClick={(e) => handleCellClick(e, ri, ci)}
                      onDoubleClick={(e) => handleCellDoubleClick(e, el.id, ri, ci)}
                      onContextMenu={(e) => handleCellContextMenu(e, ri, ci)}
                      onBlur={(e) => { if (isEditingCell(ri, ci)) { commitCell(ri, ci, e.currentTarget.textContent || ''); setEditingCell(null); } }}
                      style={cellStyle(ri, ci, {
                        width: el.columns[ci]?.width ?? 100, flexShrink: 0, display: 'flex', alignItems: 'center',
                        justifyContent: justify(el.columns[ci]?.align), padding: '0 6px', color: el.cellColor,
                        borderRight: ci < row.length - 1 ? `1px solid ${el.borderColor}` : undefined,
                        outline: isEditingCell(ri, ci) ? '1px dashed currentColor' : isSelectedCell(ri, ci) ? '1.5px solid #6d28d9' : 'none',
                        outlineOffset: isSelectedCell(ri, ci) ? -1.5 : undefined,
                        overflow: 'hidden', whiteSpace: 'nowrap',
                      })}
                    >
                      {cell}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          );
        }

        return (
          <div
            key={el.id}
            style={commonStyle}
            data-element-id={el.id}
            // Only swallow the click while selecting — with a shape/text tool
            // active, clicks must fall through to the canvas so a new element
            // can be drawn even over an existing one's (often mostly-empty)
            // bounding box, matching how Figma's drawing tools behave.
            onClick={(e) => { if (activeTool === 'select') e.stopPropagation(); }}
            onContextMenu={(e) => {
              if (activeTool !== 'select' || !onContextMenu) return;
              e.preventDefault();
              e.stopPropagation();
              // Right-clicking a member of the current multi-selection keeps
              // the whole selection intact (so "Delete"/"Bring to front" etc.
              // apply to all of them) — right-clicking anything else selects
              // just that one element first, same as every other app.
              if (!selectedElementIds.includes(el.id)) onSelect(el.id);
              onContextMenu(e, el.id);
            }}
          >
            {body}
            {isSelected && (
              <>
                <div className="pointer-events-none absolute -inset-[3px] border-2 border-brand-500" />
                {/* Resize handles only make sense for a single selection —
                    dragging a corner with multiple elements selected would
                    be ambiguous about which one's being resized. */}
                {isPrimarySelection && selectedElementIds.length === 1 && (['nw', 'ne', 'sw', 'se'] as const).map((corner) => (
                  <div
                    key={corner}
                    onPointerDown={(e) => handleResizeStart(e, el, corner)}
                    className="absolute w-2.5 h-2.5 bg-white border-2 border-brand-500 rounded-full"
                    style={{
                      top: corner.includes('n') ? -6 : undefined,
                      bottom: corner.includes('s') ? -6 : undefined,
                      left: corner.includes('w') ? -6 : undefined,
                      right: corner.includes('e') ? -6 : undefined,
                      cursor: `${corner}-resize`,
                    }}
                  />
                ))}
                {/* Rotate handle — sits in the element's own local (already
                    rotated) coordinate space along with everything else
                    here, since the rotation transform is on the shared
                    parent, so it visually follows the element's current
                    angle automatically without any extra math. */}
                {isPrimarySelection && selectedElementIds.length === 1 && !el.locked && (
                  <>
                    <div className="pointer-events-none absolute w-px h-4 bg-brand-500" style={{ top: -24, left: '50%', transform: 'translateX(-50%)' }} />
                    <div
                      onPointerDown={(e) => handleRotateStart(e, el)}
                      title="Drag to rotate (Shift snaps to 15°)"
                      className="absolute w-3 h-3 bg-white border-2 border-brand-500 rounded-full"
                      style={{ top: -30, left: '50%', transform: 'translateX(-50%)', cursor: 'grab' }}
                    />
                  </>
                )}
              </>
            )}
          </div>
        );
      })}
      {marqueeBox && (
        <div
          className="absolute border border-brand-500 bg-brand-500/10 pointer-events-none"
          style={{ left: marqueeBox.x, top: marqueeBox.y, width: marqueeBox.w, height: marqueeBox.h }}
        />
      )}
    </div>
  );
};

export default InvoiceCanvas;

import React from 'react';
import {
  Trash2, AlignLeft, AlignCenter, AlignRight, Bold, Italic, Strikethrough, Underline, Lock, Unlock, RotateCw, ChevronDown,
  AlignHorizontalJustifyStart, AlignHorizontalJustifyCenter, AlignHorizontalJustifyEnd,
  AlignVerticalJustifyStart, AlignVerticalJustifyCenter, AlignVerticalJustifyEnd,
  AlignHorizontalDistributeCenter, AlignVerticalDistributeCenter,
} from 'lucide-react';
import type { InvoiceElement } from '../../types/canvasElement';
import FontFacePicker from './FontFacePicker';

interface MultiElementInspectorProps {
  elements: InvoiceElement[];
  // Every distinct color already used somewhere in the document — shown as
  // quick-pick swatches above each color field.
  documentColors: string[];
  // Applies the same patch to every selected element in one batch.
  onUpdateAll: (patch: Partial<InvoiceElement>) => void;
  // Repositions one element at a time — align/distribute below moves each
  // element to a DIFFERENT computed x/y, which onUpdateAll's single shared
  // patch can't express.
  onUpdateOne: (id: string, patch: Partial<InvoiceElement>) => void;
  onDelete: () => void;
  onCheckpoint: () => void;
}

const LINE_STYLES: { value: string; label: string }[] = [
  { value: 'solid', label: 'Solid' },
  { value: 'dashed', label: 'Dashed' },
  { value: 'dotted', label: 'Dotted' },
  { value: 'long-dash', label: 'Long dash' },
  { value: 'dash-dot', label: 'Dash dot' },
];

const LINE_WEIGHT_PRESETS = [
  { value: 1, label: 'Thin (1px)' },
  { value: 2, label: 'Medium (2px)' },
  { value: 4, label: 'Thick (4px)' },
  { value: 8, label: 'Extra thick (8px)' },
];

// undefined = the selection has more than one distinct value for this
// property ("mixed") — every field below renders that as blank/placeholder
// rather than picking one element's value arbitrarily.
function commonValue<T>(elements: InvoiceElement[], getter: (el: any) => T): T | undefined {
  if (elements.length === 0) return undefined;
  const first = getter(elements[0] as any);
  return elements.every((el) => getter(el as any) === first) ? first : undefined;
}

// Figma/Canva-style multi-select properties panel — same fields as the
// single-element ElementInspector, but every value is "mixed-aware": a
// property that differs across the selection shows blank instead of one
// arbitrarily-chosen element's value, and editing it applies the new value
// to the whole selection at once (so users can force a shared color, font
// or size across everything selected).
const MultiElementInspector: React.FC<MultiElementInspectorProps> = ({ elements, documentColors, onUpdateAll, onUpdateOne, onDelete, onCheckpoint }) => {
  const allCustom = elements.every((el) => el.id.startsWith('custom_'));
  const anyCustom = elements.some((el) => el.id.startsWith('custom_'));

  // Align edges/centers of the selection to each other (Figma/Canva-style
  // multi-select align), using the group's own bounding box as the
  // reference frame rather than the page.
  const alignSelection = (axis: 'x' | 'y', mode: 'start' | 'center' | 'end') => {
    onCheckpoint();
    if (axis === 'x') {
      const minX = Math.min(...elements.map((el) => el.x));
      const maxX = Math.max(...elements.map((el) => el.x + el.w));
      elements.forEach((el) => {
        const x = mode === 'start' ? minX : mode === 'center' ? (minX + maxX) / 2 - el.w / 2 : maxX - el.w;
        onUpdateOne(el.id, { x: Math.round(x) });
      });
    } else {
      const minY = Math.min(...elements.map((el) => el.y));
      const maxY = Math.max(...elements.map((el) => el.y + el.h));
      elements.forEach((el) => {
        const y = mode === 'start' ? minY : mode === 'center' ? (minY + maxY) / 2 - el.h / 2 : maxY - el.h;
        onUpdateOne(el.id, { y: Math.round(y) });
      });
    }
  };

  // Evenly spaces the GAPS between elements (not their positions directly)
  // along an axis — needs 3+ elements for "even spacing" to mean anything.
  const distributeSelection = (axis: 'x' | 'y') => {
    onCheckpoint();
    const sizeKey = axis === 'x' ? 'w' : 'h';
    const sorted = [...elements].sort((a, b) => a[axis] - b[axis]);
    const first = sorted[0];
    const last = sorted[sorted.length - 1];
    const totalSpan = (last[axis] + last[sizeKey]) - first[axis];
    const totalSize = sorted.reduce((sum, el) => sum + el[sizeKey], 0);
    const gap = (totalSpan - totalSize) / (sorted.length - 1);
    let cursor = first[axis];
    sorted.forEach((el, i) => {
      if (i === 0 || i === sorted.length - 1) {
        cursor += el[sizeKey] + gap;
        return;
      }
      onUpdateOne(el.id, { [axis]: Math.round(cursor) } as Partial<InvoiceElement>);
      cursor += el[sizeKey] + gap;
    });
  };

  const field = (label: string, value: number | undefined, onChange: (n: number) => void) => (
    <label className="flex-1 min-w-0">
      <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">{label}</span>
      <input
        type="number"
        value={value === undefined ? '' : Math.round(value)}
        placeholder={value === undefined ? 'Mixed' : undefined}
        onChange={(e) => { if (e.target.value !== '') onChange(Number(e.target.value)); }}
        className="w-full bg-appBg border border-appBorder rounded-[4px] px-2 py-1.5 text-xs text-appTextPrimary placeholder:text-appTextSecondary/60"
      />
    </label>
  );

  const colorField = (label: string, value: string | undefined, onChange: (v: string) => void, wrapperClassName = '') => (
    <div className={`min-w-0 ${wrapperClassName}`}>
      <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">{label}</span>
      <div className="flex items-center gap-2">
        <input type="color" value={value || '#000000'} onChange={(e) => onChange(e.target.value)} className="w-7 h-7 rounded border border-appBorder bg-transparent cursor-pointer flex-shrink-0" />
        <input
          type="text"
          value={value || ''}
          placeholder={value === undefined ? 'Mixed' : undefined}
          onChange={(e) => onChange(e.target.value)}
          className="flex-1 min-w-0 bg-appBg border border-appBorder rounded-[4px] px-2 py-1.5 text-xs text-appTextPrimary font-mono placeholder:text-appTextSecondary/60"
        />
      </div>
      {documentColors.length > 0 && (
        <div className="flex flex-wrap gap-1 mt-1.5">
          {documentColors.map((c) => (
            <button
              key={c}
              type="button"
              title={c}
              onClick={() => onChange(c)}
              className={`w-4 h-4 rounded-full border ${value && c.toLowerCase() === value.toLowerCase() ? 'border-brand-500 ring-1 ring-brand-500' : 'border-appBorder'}`}
              style={{ backgroundColor: c }}
            />
          ))}
        </div>
      )}
    </div>
  );

  const selectField = (
    label: string,
    value: string | undefined,
    options: { value: string; label: string; style?: React.CSSProperties }[],
    onChange: (v: string) => void,
    selectStyle?: React.CSSProperties
  ) => (
    <label className="block">
      <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">{label}</span>
      <div className="relative">
        <select
          value={value ?? '__mixed__'}
          onChange={(e) => onChange(e.target.value)}
          className="w-full appearance-none bg-appBg border border-appBorder rounded-[4px] pl-2 pr-7 py-1.5 text-xs text-appTextPrimary"
          style={selectStyle}
        >
          {value === undefined && <option value="__mixed__" disabled hidden>Mixed</option>}
          {options.map((o) => (
            <option key={o.value} value={o.value} style={o.style}>{o.label}</option>
          ))}
        </select>
        <ChevronDown size={12} className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-appTextSecondary" />
      </div>
    </label>
  );

  // Toggle buttons (bold/italic/underline/strikethrough/lock): "active"
  // only when EVERY selected element already has it on; clicking flips
  // everything to the opposite of that — off if all were on, on otherwise.
  const toggleButton = (title: string, active: boolean, Icon: React.ElementType, onClick: () => void) => (
    <button
      title={title}
      onClick={onClick}
      className={`p-1.5 rounded border ${active ? 'border-brand-500 text-brand-500' : 'border-appBorder text-appTextSecondary'}`}
    >
      <Icon size={13} />
    </button>
  );

  const types = new Set(elements.map((el) => el.type));
  const allText = types.size === 1 && types.has('text');
  const allShapeLike = types.size >= 1 && [...types].every((t) => t === 'rect' || t === 'ellipse');
  const allRect = types.size === 1 && types.has('rect');
  const allLines = types.size === 1 && types.has('line');

  const rotation = commonValue(elements, (el) => el.rotation ?? 0);
  const allLocked = elements.every((el) => el.locked);
  const opacity = commonValue(elements, (el) => el.opacity ?? 1);
  const shadowEnabled = commonValue(elements, (el) => !!el.shadowEnabled);
  const shadowColor = commonValue(elements, (el) => el.shadowColor);
  const shadowBlur = commonValue(elements, (el) => el.shadowBlur);
  const shadowOffsetX = commonValue(elements, (el) => el.shadowOffsetX);
  const shadowOffsetY = commonValue(elements, (el) => el.shadowOffsetY);

  return (
    <div className="space-y-5">
      <div>
        <h5 className="text-xs font-bold text-appTextPrimary mb-2">{elements.length} elements selected</h5>
        <p className="text-[11px] text-appTextSecondary mb-3">Drag any of them to move the whole group together. Values that differ across the selection show blank — set one to apply it to all.</p>

        <label className="block mb-2">
          <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">Opacity</span>
          <div className="flex items-center gap-2">
            <input
              type="range"
              min={0}
              max={100}
              value={opacity === undefined ? 100 : Math.round(opacity * 100)}
              onChange={(e) => onUpdateAll({ opacity: Number(e.target.value) / 100 })}
              className="flex-1 accent-brand-500"
            />
            <span className="w-10 text-right text-[10px] font-mono text-appTextSecondary">{opacity === undefined ? 'Mixed' : `${Math.round(opacity * 100)}%`}</span>
          </div>
        </label>

        <div className="flex gap-2 items-end">
          <label className="flex-1">
            <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">Rotation</span>
            <div className="flex items-center gap-1">
              <RotateCw size={12} className="text-appTextSecondary flex-shrink-0" />
              <input
                type="number"
                value={rotation === undefined ? '' : Math.round(rotation)}
                placeholder={rotation === undefined ? 'Mixed' : undefined}
                onChange={(e) => { if (e.target.value !== '') onUpdateAll({ rotation: Number(e.target.value) }); }}
                className="w-full bg-appBg border border-appBorder rounded-[4px] px-2 py-1.5 text-xs text-appTextPrimary placeholder:text-appTextSecondary/60"
              />
            </div>
          </label>
          <button
            title={allLocked ? 'Unlock (Alt+Shift+L)' : 'Lock (Alt+Shift+L)'}
            onClick={() => onUpdateAll({ locked: !allLocked })}
            className={`p-1.5 rounded border ${allLocked ? 'border-brand-500 text-brand-500' : 'border-appBorder text-appTextSecondary'}`}
          >
            {allLocked ? <Lock size={14} /> : <Unlock size={14} />}
          </button>
        </div>

        <div className="mt-3">
          <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">Align selection</span>
          <div className="flex items-center gap-1">
            <button title="Align left edges" onClick={() => alignSelection('x', 'start')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignHorizontalJustifyStart size={13} /></button>
            <button title="Align horizontal centers" onClick={() => alignSelection('x', 'center')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignHorizontalJustifyCenter size={13} /></button>
            <button title="Align right edges" onClick={() => alignSelection('x', 'end')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignHorizontalJustifyEnd size={13} /></button>
            <span className="w-px h-4 bg-appBorder mx-0.5" />
            <button title="Align top edges" onClick={() => alignSelection('y', 'start')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignVerticalJustifyStart size={13} /></button>
            <button title="Align vertical centers" onClick={() => alignSelection('y', 'center')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignVerticalJustifyCenter size={13} /></button>
            <button title="Align bottom edges" onClick={() => alignSelection('y', 'end')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignVerticalJustifyEnd size={13} /></button>
          </div>
          {elements.length >= 3 && (
            <div className="flex items-center gap-1 mt-1.5">
              <button title="Distribute horizontally" onClick={() => distributeSelection('x')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignHorizontalDistributeCenter size={13} /></button>
              <button title="Distribute vertically" onClick={() => distributeSelection('y')} className="p-1.5 rounded border border-appBorder text-appTextSecondary hover:border-brand-500 hover:text-brand-500"><AlignVerticalDistributeCenter size={13} /></button>
            </div>
          )}
        </div>
      </div>

      <div className="pt-1 border-t border-appBorder">
        <div className="flex items-center justify-between pt-3 mb-2">
          <h5 className="text-xs font-bold text-appTextPrimary">Drop shadow</h5>
          <input
            type="checkbox"
            checked={!!shadowEnabled}
            onChange={(e) => onUpdateAll({ shadowEnabled: e.target.checked } as Partial<InvoiceElement>)}
            className="w-4 h-4 accent-brand-500 cursor-pointer"
          />
        </div>
        {shadowEnabled && (
          <div className="space-y-2">
            {colorField('Color', shadowColor || '#000000', (v) => onUpdateAll({ shadowColor: v } as Partial<InvoiceElement>))}
            <div className="flex gap-2">
              {field('Blur', shadowBlur ?? 8, (n) => onUpdateAll({ shadowBlur: n } as Partial<InvoiceElement>))}
              {field('Offset X', shadowOffsetX ?? 0, (n) => onUpdateAll({ shadowOffsetX: n } as Partial<InvoiceElement>))}
              {field('Offset Y', shadowOffsetY ?? 4, (n) => onUpdateAll({ shadowOffsetY: n } as Partial<InvoiceElement>))}
            </div>
          </div>
        )}
      </div>

      {allText && (() => {
        const fontFamily = commonValue(elements, (el) => el.fontFamily || 'Inter');
        const fontSize = commonValue(elements, (el) => el.fontSize);
        const fontWeight = commonValue(elements, (el) => el.fontWeight);
        const align = commonValue(elements, (el) => el.align);
        const color = commonValue(elements, (el) => el.color);
        const stroke = commonValue(elements, (el) => el.stroke);
        const strokeWidth = commonValue(elements, (el) => el.strokeWidth);
        const allBold = elements.every((el: any) => el.fontWeight >= 700);
        const allItalic = elements.every((el: any) => el.italic);
        const allUnderline = elements.every((el: any) => el.underline);
        const allStrike = elements.every((el: any) => el.strikethrough);

        return (
          <div className="space-y-3 pt-1 border-t border-appBorder">
            <h5 className="text-xs font-bold text-appTextPrimary pt-3">Text</h5>

            <FontFacePicker
              value={fontFamily}
              onChange={(v) => onUpdateAll({ fontFamily: v } as Partial<InvoiceElement>)}
            />

            <div className="flex gap-2">
              {field('Size', fontSize, (n) => onUpdateAll({ fontSize: n } as Partial<InvoiceElement>))}
              <div className="flex-1">
                {selectField(
                  'Weight',
                  fontWeight === undefined ? undefined : String(fontWeight),
                  [400, 500, 600, 700, 800].map((w) => ({ value: String(w), label: String(w) })),
                  (v) => onUpdateAll({ fontWeight: Number(v) } as Partial<InvoiceElement>)
                )}
              </div>
            </div>

            <div className="flex items-center gap-1">
              {toggleButton('Bold (Ctrl/Cmd+B)', allBold, Bold, () => onUpdateAll({ fontWeight: allBold ? 400 : 700 } as Partial<InvoiceElement>))}
              {toggleButton('Italic (Ctrl/Cmd+I)', allItalic, Italic, () => onUpdateAll({ italic: !allItalic } as Partial<InvoiceElement>))}
              {toggleButton('Underline (Ctrl/Cmd+U)', allUnderline, Underline, () => onUpdateAll({ underline: !allUnderline } as Partial<InvoiceElement>))}
              {toggleButton('Strikethrough', allStrike, Strikethrough, () => onUpdateAll({ strikethrough: !allStrike } as Partial<InvoiceElement>))}
            </div>

            <div className="flex items-center gap-1">
              {(['left', 'center', 'right'] as const).map((a) => {
                const Icon = a === 'left' ? AlignLeft : a === 'center' ? AlignCenter : AlignRight;
                return (
                  <button
                    key={a}
                    title={`Align ${a}`}
                    onClick={() => onUpdateAll({ align: a } as Partial<InvoiceElement>)}
                    className={`p-1.5 rounded border ${align === a ? 'border-brand-500 text-brand-500' : 'border-appBorder text-appTextSecondary'}`}
                  >
                    <Icon size={13} />
                  </button>
                );
              })}
            </div>

            {colorField('Color', color, (v) => onUpdateAll({ color: v } as Partial<InvoiceElement>))}

            <div className="pt-2 border-t border-appBorder space-y-3">
              <h5 className="text-xs font-bold text-appTextPrimary pt-1">Text box border</h5>
              <div className="flex gap-2 items-end">
                {colorField('Border color', stroke, (v) => onUpdateAll({ stroke: v } as Partial<InvoiceElement>), 'flex-[2] min-w-0')}
                <label className="w-16 flex-shrink-0">
                  <span className="block text-[9px] font-semibold uppercase tracking-wide text-appTextSecondary mb-1">Width</span>
                  <input
                    type="number"
                    value={strokeWidth === undefined ? '' : Math.round(strokeWidth)}
                    placeholder={strokeWidth === undefined ? 'Mixed' : undefined}
                    onChange={(e) => { if (e.target.value !== '') onUpdateAll({ strokeWidth: Number(e.target.value) } as Partial<InvoiceElement>); }}
                    className="w-full bg-appBg border border-appBorder rounded-[4px] px-2 py-1.5 text-xs text-appTextPrimary placeholder:text-appTextSecondary/60"
                  />
                </label>
              </div>
            </div>
          </div>
        );
      })()}

      {allShapeLike && !allLines && (() => {
        const fill = commonValue(elements, (el) => el.fill);
        const stroke = commonValue(elements, (el) => el.stroke);
        const strokeWidth = commonValue(elements, (el) => el.strokeWidth);
        const radius = commonValue(elements, (el) => el.radius);

        return (
          <div className="space-y-3 pt-1 border-t border-appBorder">
            <h5 className="text-xs font-bold text-appTextPrimary pt-3">Appearance</h5>
            {colorField('Fill', fill, (v) => onUpdateAll({ fill: v } as Partial<InvoiceElement>))}
            {colorField('Stroke', stroke, (v) => onUpdateAll({ stroke: v } as Partial<InvoiceElement>))}
            {field('Stroke width', strokeWidth ?? 0, (n) => onUpdateAll({ strokeWidth: n } as Partial<InvoiceElement>))}
            {allRect && field('Corner radius', radius ?? 0, (n) => onUpdateAll({ radius: n } as Partial<InvoiceElement>))}
          </div>
        );
      })()}

      {allLines && (() => {
        const fill = commonValue(elements, (el) => el.fill);
        const lineStyle = commonValue(elements, (el) => el.lineStyle ?? 'solid');
        const strokeWidth = commonValue(elements, (el) => el.strokeWidth ?? 2);

        return (
          <div className="space-y-3 pt-1 border-t border-appBorder">
            <h5 className="text-xs font-bold text-appTextPrimary pt-3">Line</h5>
            {colorField('Color', fill, (v) => onUpdateAll({ fill: v } as Partial<InvoiceElement>))}
            {selectField('Style', lineStyle, LINE_STYLES, (v) => onUpdateAll({ lineStyle: v } as Partial<InvoiceElement>))}
            <div className="flex gap-2 items-end">
              <div className="flex-1">
                {selectField(
                  'Weight preset',
                  strokeWidth === undefined ? undefined : (LINE_WEIGHT_PRESETS.some((p) => p.value === strokeWidth) ? String(strokeWidth) : ''),
                  [{ value: '', label: 'Custom' }, ...LINE_WEIGHT_PRESETS.map((p) => ({ value: String(p.value), label: p.label }))],
                  (v) => { if (v) onUpdateAll({ strokeWidth: Number(v) } as Partial<InvoiceElement>); }
                )}
              </div>
              {field('Weight (px)', strokeWidth, (n) => onUpdateAll({ strokeWidth: Math.max(1, n) } as Partial<InvoiceElement>))}
            </div>
          </div>
        );
      })()}

      {anyCustom && (
        <button
          onClick={onDelete}
          className="w-full flex items-center justify-center gap-1.5 text-xs font-semibold text-appError border border-appError/40 rounded-[4px] py-2 hover:bg-appError/10"
        >
          <Trash2 size={13} /> {allCustom ? 'Delete selected' : 'Delete selected (custom only)'}
        </button>
      )}
    </div>
  );
};

export default MultiElementInspector;

import React, { useEffect, useState } from 'react';
import { Check, Lock, Save, Trash2, FileStack, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';
import { useDocumentStore, SAMPLE_DOCUMENT_DATA } from '../../store/documentStore';
import { useChatStore } from '../../store/chatStore';
import { useAuthStore } from '../../store/authStore';
import { renderTemplate } from '../../utils/templateRenderer';
import { saveCustomTemplate, getCustomTemplates, getCustomTemplateDetail, deleteCustomTemplate, type CustomTemplateSummary } from '../../api/documents';
import type { Template } from '../../types';
import type { InvoiceElement } from '../../types/canvasElement';

interface TemplateCardItemProps {
  template: Template;
  isSelected: boolean;
  isLocked: boolean;
  sampleData: Record<string, unknown>;
  accentColor: string;
  currentDocType: string;
  onSelect: (id: string) => void;
}

const TemplateCardItem: React.FC<TemplateCardItemProps> = React.memo(({
  template,
  isSelected,
  isLocked,
  sampleData,
  accentColor,
  currentDocType,
  onSelect,
}) => {
  const renderedHtml = React.useMemo(() => {
    return renderTemplate(
      template.template_id,
      sampleData,
      {
        headerAlignment: 'left',
        fontSize: 'medium',
        showLogo: false,
        showNotes: true,
        sectionOrder: ['header', 'client_details', 'line_items', 'total', 'notes'],
      },
      accentColor,
      currentDocType
    );
  }, [template.template_id, sampleData, accentColor, currentDocType]);

  return (
    <motion.button
      type="button"
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      whileHover={{ scale: isLocked ? 1 : 1.05 }}
      whileTap={{ scale: isLocked ? 1 : 0.95 }}
      transition={{ duration: 0.2, type: 'spring', stiffness: 300 }}
      key={template.template_id}
      onClick={(e) => {
        e.preventDefault();
        if (!isLocked) onSelect(template.template_id);
      }}
      disabled={isLocked}
      id={`template-${template.template_id}`}
      className={`relative rounded-none overflow-hidden border-2 transition-all duration-200 group
        ${isSelected
          ? 'border-brand-500 shadow-glow'
          : 'border-appBorder hover:border-brand-500/50'
        }
        ${isLocked ? 'opacity-60 cursor-not-allowed' : 'cursor-pointer'}
      `}
    >
      {/* Thumbnail */}
      <div className="aspect-[3/4] bg-appSurface flex items-center justify-center relative overflow-hidden">
        {template.thumbnail_url ? (
          <img
            src={template.thumbnail_url}
            alt={template.name}
            className="w-full h-full object-cover"
          />
        ) : (
          <svg viewBox="0 0 595 842" className="w-full h-full pointer-events-none">
            <foreignObject width="595" height="842">
              <div
                className="w-full h-full bg-white"
                dangerouslySetInnerHTML={{ __html: renderedHtml }}
              />
            </foreignObject>
          </svg>
        )}
      </div>

      {/* Label */}
      <div className="px-1.5 py-1.5 bg-appSurface border-t border-appBorder">
        <p className="text-[10px] text-appTextPrimary font-medium truncate">{template.name}</p>
      </div>

      {/* Selected indicator */}
      {isSelected && (
        <div className="absolute top-1 right-1 w-5 h-5 bg-brand-500 rounded-full flex items-center justify-center">
          <Check size={10} className="text-white" />
        </div>
      )}

      {/* Pro lock */}
      {isLocked && (
        <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
          <div className="flex items-center gap-1 bg-appSurface px-2 py-1 rounded-full">
            <Lock size={10} className="text-accent-amber-400" />
            <span className="text-[9px] text-accent-amber-400 font-semibold">PRO</span>
          </div>
        </div>
      )}
    </motion.button>
  );
});

// "Your Templates" — user-saved static snapshots of the canvas (see
// applyCustomTemplateElements's own comment for why these can't be
// data-bound generators like the built-in templates). Kept as a separate
// section below the built-in grid rather than merged into TemplateCardItem,
// since rendering a faithful thumbnail from raw canvasElements would need
// a small standalone renderer of its own — out of scope here, so these
// are plain named cards instead of visual previews.
const CustomTemplatesSection: React.FC<{ currentDocType: string }> = ({ currentDocType }) => {
  const { canvasElements, pageWidth, pageHeight, pageBackgroundColor, applyCustomTemplateElements } = useDocumentStore();
  const [templates, setTemplates] = useState<CustomTemplateSummary[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [applyingId, setApplyingId] = useState<string | null>(null);
  const [namingOpen, setNamingOpen] = useState(false);
  const [nameValue, setNameValue] = useState('');
  const [error, setError] = useState<string | null>(null);

  const loadTemplates = () => {
    setLoading(true);
    getCustomTemplates(currentDocType)
      .then((res) => setTemplates(res.templates))
      .catch(() => setError('Could not load your saved templates.'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadTemplates();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentDocType]);

  const handleSave = async () => {
    if (!nameValue.trim() || !canvasElements) return;
    setSaving(true);
    setError(null);
    try {
      await saveCustomTemplate({
        name: nameValue.trim(),
        documentType: currentDocType,
        canvasElements: canvasElements as unknown[],
        pageWidth,
        pageHeight,
        pageBackgroundColor,
      });
      setNamingOpen(false);
      setNameValue('');
      loadTemplates();
    } catch {
      setError('Could not save this template — try again.');
    } finally {
      setSaving(false);
    }
  };

  const handleApply = async (id: string) => {
    setApplyingId(id);
    setError(null);
    try {
      const detail = await getCustomTemplateDetail(id);
      applyCustomTemplateElements(
        detail.canvasElements as InvoiceElement[],
        detail.pageWidth,
        detail.pageHeight,
        detail.pageBackgroundColor
      );
    } catch {
      setError('Could not load that template — try again.');
    } finally {
      setApplyingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    setTemplates((cur) => cur.filter((t) => t.id !== id));
    try {
      await deleteCustomTemplate(id);
    } catch {
      loadTemplates();
    }
  };

  return (
    <div className="p-4 border-b border-appBorder space-y-3">
      <div className="flex items-center justify-between">
        <h5 className="text-xs font-bold text-appTextPrimary flex items-center gap-1.5">
          <FileStack size={13} /> Your Templates
        </h5>
        {!namingOpen && (
          <button
            onClick={() => setNamingOpen(true)}
            disabled={!canvasElements}
            title={canvasElements ? 'Save current design as a template' : 'Nothing to save yet'}
            className="flex items-center gap-1 text-[10px] font-semibold text-brand-500 hover:underline disabled:opacity-40 disabled:cursor-not-allowed"
          >
            <Save size={11} /> Save current
          </button>
        )}
      </div>

      {namingOpen && (
        <div className="flex items-center gap-1.5">
          <input
            type="text"
            autoFocus
            value={nameValue}
            onChange={(e) => setNameValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); if (e.key === 'Escape') setNamingOpen(false); }}
            placeholder="Template name…"
            className="flex-1 min-w-0 bg-appBg border border-appBorder rounded-[4px] px-2 py-1.5 text-xs text-appTextPrimary"
          />
          <button
            onClick={handleSave}
            disabled={saving || !nameValue.trim()}
            className="px-2.5 py-1.5 rounded-[4px] bg-brand-500 text-white text-xs font-semibold disabled:opacity-50"
          >
            {saving ? <Loader2 size={12} className="animate-spin" /> : 'Save'}
          </button>
        </div>
      )}

      {error ? (
        <p className="text-[10px] text-appError">{error}</p>
      ) : loading ? (
        <p className="text-[10px] text-appTextSecondary">Loading…</p>
      ) : templates.length === 0 ? (
        <p className="text-[10px] text-appTextSecondary">
          No saved templates yet — style a document the way you like it, then "Save current" to reuse that exact layout next time.
        </p>
      ) : (
        <div className="space-y-1.5">
          {templates.map((t) => (
            <div key={t.id} className="flex items-center gap-2 px-2.5 py-2 bg-appBg border border-appBorder rounded-[4px]">
              <span className="flex-1 min-w-0 truncate text-xs text-appTextPrimary font-medium">{t.name}</span>
              <button
                onClick={() => handleApply(t.id)}
                disabled={applyingId === t.id}
                className="text-[10px] font-semibold text-brand-500 hover:underline flex-shrink-0"
              >
                {applyingId === t.id ? <Loader2 size={11} className="animate-spin" /> : 'Apply'}
              </button>
              <button
                onClick={() => handleDelete(t.id)}
                title="Delete"
                className="p-1 text-appTextSecondary hover:text-appError flex-shrink-0"
              >
                <Trash2 size={12} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const TemplateSelector: React.FC = () => {
  const { templates, selectedTemplate, selectTemplate, accentColor } = useDocumentStore();
  const { documentType, collectedSlots, collectedData } = useChatStore();
  const { user } = useAuthStore();
  const isPro = user?.plan === 'pro';

  const currentDocType = documentType || 'invoice';

  if (templates.length === 0) return null;

  const sampleData = SAMPLE_DOCUMENT_DATA[currentDocType] || SAMPLE_DOCUMENT_DATA.invoice;
  const activeData = (collectedSlots && Object.keys(collectedSlots).length > 0)
    ? { documentType: currentDocType, ...collectedSlots }
    : (collectedData || sampleData);

  return (
    <div id="template-selector">
      <CustomTemplatesSection currentDocType={currentDocType} />
      <div className="p-4 grid grid-cols-1 gap-4">
        {templates.map((template: Template) => {
          const isSelected = selectedTemplate === template.template_id;
          const isLocked = template.tier === 'pro' && !isPro;

          return (
            <TemplateCardItem
              key={template.template_id}
              template={template}
              isSelected={isSelected}
              isLocked={isLocked}
              sampleData={activeData}
              accentColor={accentColor}
              currentDocType={currentDocType}
              onSelect={selectTemplate}
            />
          );
        })}
      </div>
    </div>
  );
};

export default TemplateSelector;

import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { useThemeStore } from '../../store/themeStore';

const BackgroundEffects: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const theme = useThemeStore((state: any) => state.theme);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let particles: { x: number; y: number; size: number; vx: number; vy: number; alpha: number }[] = [];
    let animationFrameId: number;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initParticles();
    };

    const initParticles = () => {
      particles = [];
      const numParticles = Math.min(Math.floor((window.innerWidth * window.innerHeight) / 15000), 100);
      for (let i = 0; i < numParticles; i++) {
        particles.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          size: Math.random() * 1.5 + 0.5,
          vx: (Math.random() - 0.5) * 0.5,
          // Gravity drift downwards
          vy: Math.random() * 0.5 + 0.2,
          alpha: Math.random() * 0.5 + 0.1,
        });
      }
    };

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const isDark = theme === 'dark';
      const colorPrefix = isDark ? '255, 255, 255' : '15, 23, 42';

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];

        // Apply gravity/velocity
        p.x += p.vx;
        p.y += p.vy;

        // Wrap around boundaries
        if (p.y > canvas.height) p.y = 0;
        if (p.x > canvas.width) p.x = 0;
        if (p.x < 0) p.x = canvas.width;

        // Draw particle
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${colorPrefix}, ${p.alpha})`;
        ctx.fill();

        // Connect nearby particles
        for (let j = i + 1; j < particles.length; j++) {
          const p2 = particles[j];
          const dx = p.x - p2.x;
          const dy = p.y - p2.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < 120) {
            ctx.beginPath();
            ctx.strokeStyle = `rgba(${colorPrefix}, ${((120 - dist) / 120) * 0.15})`;
            ctx.lineWidth = 0.5;
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
          }
        }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    window.addEventListener('resize', resize);
    resize();
    draw();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [theme]);

  const isDark = theme === 'dark';

  return (
    <div className="fixed inset-0 -z-10 overflow-hidden pointer-events-none bg-transparent">
      {/* Gravity Particles Canvas */}
      <canvas ref={canvasRef} className="absolute inset-0 z-0 opacity-60" />

      {/* Subtle Noise / Grid Pattern */}
      <div 
        className="absolute inset-0 opacity-[0.03] dark:opacity-[0.03] z-10"
        style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23${isDark ? 'ffffff' : '0f172a'}' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
        }}
      />

      {/* Floating Orbs using Framer Motion */}
      <motion.div 
        className={`absolute top-0 -left-4 w-96 h-96 rounded-full filter blur-[120px] z-20 ${
          isDark ? 'bg-brand-500/20 mix-blend-screen' : 'bg-brand-500/10 mix-blend-multiply'
        }`}
        animate={{
          x: ['0vw', '25vw', '-15vw', '0vw'],
          y: ['0vh', '-20vh', '15vh', '0vh'],
          scale: [1, 1.2, 0.8, 1],
        }}
        transition={{
          duration: 18,
          repeat: Infinity,
          ease: "easeInOut",
        }}
      />

      <motion.div 
        className={`absolute top-0 -right-4 w-96 h-96 rounded-full filter blur-[120px] z-20 ${
          isDark ? 'bg-purple-500/20 mix-blend-screen' : 'bg-purple-500/10 mix-blend-multiply'
        }`}
        animate={{
          x: ['0vw', '-25vw', '15vw', '0vw'],
          y: ['0vh', '20vh', '-15vh', '0vh'],
          scale: [1, 1.3, 0.9, 1],
        }}
        transition={{
          duration: 22,
          repeat: Infinity,
          ease: "easeInOut",
          delay: 2,
        }}
      />

      <motion.div 
        className={`absolute -bottom-8 left-20 w-96 h-96 rounded-full filter blur-[120px] z-20 ${
          isDark ? 'bg-cyan-500/20 mix-blend-screen' : 'bg-cyan-500/10 mix-blend-multiply'
        }`}
        animate={{
          x: ['0vw', '20vw', '-20vw', '0vw'],
          y: ['0vh', '-25vh', '20vh', '0vh'],
          scale: [1, 1.1, 0.85, 1],
        }}
        transition={{
          duration: 25,
          repeat: Infinity,
          ease: "easeInOut",
          delay: 4,
        }}
      />
    </div>
  );
};

export default BackgroundEffects;

import React, { useEffect, useRef, useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import {
  LogOut,
  User as UserIcon,
  Menu,
  X,
  Sparkles,
  Sun,
  Moon,
  ExternalLink,
  Home,
  LayoutDashboard
} from 'lucide-react';
import { useAuthStore } from '../../store/authStore';
import { useThemeStore } from '../../store/themeStore';
import Button from '../ui/Button';
// logo-left1 (dark charcoal + purple line art) reads clearly against the
// light navbar; logo-left (white + blue line art) is the dark-mode
// counterpart, since a dark mark would disappear against a dark navbar.
import logoForLightMode from '../../assets/images/logo-left1.png';
import logoForDarkMode from '../../assets/images/logo-left.png';
import LogoutConfirmModal from './LogoutConfirmModal';

const Navbar: React.FC = () => {
  const { user, isAuthenticated, isGuest, logout } = useAuthStore();
  const theme = useThemeStore((state: any) => state.theme);
  const toggleTheme = useThemeStore((state: any) => state.toggleTheme);
  const navigate = useNavigate();

  const [mobileOpen, setMobileOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const [profileMenuOpen, setProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (!profileMenuOpen) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (profileMenuRef.current && !profileMenuRef.current.contains(e.target as Node)) {
        setProfileMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [profileMenuOpen]);

  const handleLogoutClick = () => {
    setShowLogoutModal(true);
  };

  const confirmLogout = async () => {
    setIsLoggingOut(true);
    try {
      await logout();
      setShowLogoutModal(false);
      navigate('/');
    } catch {
      // Continue cleanup even on error
      setShowLogoutModal(false);
      navigate('/');
    } finally {
      setIsLoggingOut(false);
    }
  };

  const location = useLocation();
  const isLandingPage = location.pathname === '/';
  const isBuilderPage = location.pathname === '/builder';
  const isAuthPage = location.pathname === '/login' || location.pathname === '/register';
  const showPublicNav = isLandingPage || isAuthPage || location.pathname === '/pricing' || location.pathname === '/verify-email' || location.pathname === '/password-reset';

  const scrollToSection = (sectionId: string) => (e: React.MouseEvent) => {
    e.preventDefault();
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const el = document.getElementById(sectionId);
        if (el) el.scrollIntoView({ behavior: 'smooth' });
      }, 150);
    } else {
      const el = document.getElementById(sectionId);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 h-14 flex items-center bg-gradient-to-br from-brand-200/12 to-white dark:from-brand-500/8 dark:to-appSurface border-b border-brand-300/30 ${
        scrolled ? 'backdrop-blur-md shadow-sm' : ''
      }`}
    >
      <div className="w-full h-full pl-4 sm:pl-6 lg:pl-8">
        <div className="flex items-stretch justify-between h-full">
          {/* Logo — always goes to the actual landing page. Signed-in users
              use /?preview=1 so LandingPage's auto-redirect-to-/dashboard
              effect doesn't immediately bounce them straight back. */}
          <Link to={isAuthenticated ? '/?preview=1' : '/'} className="flex items-center gap-2.5 group flex-shrink-0" id="navbar-logo">
            <img
              src={theme === 'dark' ? logoForDarkMode : logoForLightMode}
              alt=""
              className="w-8 h-8 object-contain"
            />
            <span className="text-xl font-bold text-appTextPrimary">
              Doc<span className="text-appPrimary">Craft</span>
            </span>
          </Link>

          {/* Desktop Nav Links — Show all public tabs except Admin */}
          {showPublicNav && (
            <div className="hidden md:flex items-center gap-8 mx-auto">
              <a
                href="#features"
                onClick={scrollToSection('features')}
                className="text-sm font-medium text-appTextSecondary hover:text-appTextPrimary transition-colors"
                id="nav-features"
              >
                Features
              </a>
              <a
                href="#solution"
                onClick={scrollToSection('solution')}
                className="text-sm font-medium text-appTextSecondary hover:text-appTextPrimary transition-colors"
                id="nav-solution"
              >
                Solution
              </a>
              <a
                href="#pricing"
                onClick={scrollToSection('pricing')}
                className="text-sm font-medium text-appTextSecondary hover:text-appTextPrimary transition-colors"
                id="nav-pricing"
              >
                Pricing
              </a>
              <a
                href="#about"
                onClick={scrollToSection('about')}
                className="text-sm font-medium text-appTextSecondary hover:text-appTextPrimary transition-colors"
                id="nav-about"
              >
                About
              </a>
            </div>
          )}

          {/* Desktop Action Buttons & Theme Toggle (Right) — plain icon
              cluster (no border/background boxes), matching a minimal
