      </AnimatePresence>

      {/* ─── 2FA DISABLE CONFIRM MODAL ───────────────────────── */}
      <AnimatePresence>
        {isDisableOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setIsDisableOpen(false)}
              className="absolute inset-0 bg-appBg/60 backdrop-blur-md"
