  if (taxRate > 0) {
    els.push(
      text('totals_tax_label', { x: 349, y: totalsY + 28, w: 100, h: 14, fontSize: 10, fontWeight: 500, color: dark, align: 'left', text: `Tax (${taxRate}%)`, section: 'totals', zIndex: 1 }),
